('world-needs-sunday', 'col-prob-cero-array', 'Cero 的数组（构造序列的最长上升子序列）', $AKB453$## 题目描述

Marton 的朋友 Cero 有一个由 $N$ 个正整数组成的数组。

首先 Cero 会在黑板上写下这个数组中的第一个数字。接下来他会在之前写下的所有数的左边或者右边写下一个数字。重复以上操作得到一个序列。

请注意，根据上述方法构造出的两个序列相同当且仅当每一个数字写下的顺序完全相同。例如，`1,1` 可能和 `1,1` 不同——前者的第二个数在第一个数的左边，后者的第二个数在第一个数的右边。

求这些数组成的所有序列中，最长严格递增子序列长度的最大值 $M$，以及所有最长严格递增子序列长度等于 $M$ 的序列中，最长严格递增子序列个数的总和。考虑到答案可能很大，只需输出对 $10^9 + 7$ 取模的值。

### 输入格式

第一行包含一个正整数 $N$。

接下来的一行包含 $N$ 个正整数，表示按顺序给出的这个数组的各个元素。

### 输出格式

仅一行，输出最长子序列长度以及总个数模上 $10^9 + 7$ 的值。

### 数据范围与约定

- 对于 30% 的数据，满足 $N \le 20$
- 对于 50% 的数据，满足 $N \le 10^3$
- 对于 100% 的数据，满足 $N \le 2 \times 10^5$，数组中的每个元素 $\le 10^9$
- 答案需对 $10^9 + 7$ 取模

## 样例

> 本题来源与官方样例暂未考证。以下示例由本文档自造，并已用「枚举全部 $2^{N-1}$ 种写法 + 逐个统计 LIS 条数」的独立暴力验证。

### 样例输入

```
4
1 3 2 4
```

### 样例输出

```
3 6
```

**说明**：$N = 4$，共有 $2^{3} = 8$ 种写法。这些序列中最长严格递增子序列长度的最大值为 $M = 3$；在 LIS 长度恰为 3 的那些序列中，LIS 的条数之和为 6，故输出 `3 6`。

## 解题思路

### 第一步：构造转化（本题最核心的难点）

题目描述的构造过程是：先写第一个数，之后每个数只能放在当前序列的**最左端或最右端**。直接枚举所有可能的序列是不可行的（共有 $2^{n-1}$ 种），必须找到等价的数学刻画。

**关键观察**：每个可能的序列，都可以看作是从原序列中选择一个子序列，将该子序列**翻转**后拼接到剩余部分的左侧。

```
原序列:       A1  A2  A3  A4  A5  A6  A7
                        ↓
选择子序列:        A2     A4     A6  (选中的元素按原序)
                        ↓
翻转子序列:   A6     A4     A2         (逆序)
                        ↓
拼接得到:     A6  A1  A4  A3  A2  A5  A7
              ↑↑↑↑↑                    ↑↑↑↑↑
              翻折过来的部分              未翻折的部分
```

换句话说，每个可能的序列 = 一个"翻转前缀" + 一个"原始后缀"。翻转前缀是原序列某个子序列的逆序，原始后缀是剩下的元素按原序排列。

### 第二步：LIS 结构分析

有了上述转化，我们分析可能序列的 LIS（最长严格上升子序列）结构：

- 翻转前缀部分（从原序列中选出的子序列的逆序）在原序列中是**严格下降**的（因为逆序后上升 = 原序下降）
- 原始后缀部分在原序列中是**严格上升**的
- 一个可能序列的 LIS，由"翻转前缀中贡献的上升段"和"原始后缀中贡献的上升段"拼接而成

更精确地说：对于原序列的某个位置 $i$，可能序列的 LIS 可以表示为：

- 一个以 $i$ 结尾（向左方向）的**严格下降子序列**（贡献翻转前缀部分）
- 一个以 $i$ 开头（向右方向）的**严格上升子序列**（贡献原始后缀部分）
- 两段在位置 $i$ 处衔接（$i$ 同时属于两段，因此长度减 1）

因此，最长 LIS 长度为：

$$M = \max_{i=1}^{n} \left( \text{len}_a[i] + \text{len}_b[i] - 1 \right)$$

其中：
- $\text{len}_a[i]$ = 以 $i$ 结尾的、向左方向的最长严格下降子序列长度（即在原序列中从 $i$ 向左看，$A[i]$ 能接在哪些比它大的元素后面）
- $\text{len}_b[i]$ = 以 $i$ 开头的、向右方向的最长严格上升子序列长度

### 第三步：方案数计算

对于每个满足 $\text{len}_a[i] + \text{len}_b[i] - 1 = M$ 的位置 $i$，设 $\text{cnt}_a[i]$ 和 $\text{cnt}_b[i]$ 分别为对应方向的方案数，则：

$$\text{cnt}(i) = \text{cnt}_a[i] \times \text{cnt}_b[i] \times 2^{n - M}$$

其中 $2^{n-M}$ 的含义是**不在 LIS 中的元素**的放置方式：

**情况 1：$A_1$ 属于 LIS**

- 不在 LIS 中的元素有 $n - M$ 个
- 每个元素可以翻到左边或不翻（2 种选择）
- 方案数：$2^{n-M}$

**情况 2：$A_1$ 不属于 LIS**

- 不在 LIS 中的元素有 $n - M$ 个（包括 $A_1$）
- $A_1$ 必须翻到左边（只有 1 种选择，因为它不在 LIS 中却必须出现在翻转前缀中）
- 其他 $n - M - 1$ 个元素各有 2 种选择
- 衔接元素（同时属于两段的那个元素）不是 $A_1$，所以它可以跟着任一序列，翻不翻都可以，额外乘以 2
- 方案数：$1 \times 2^{n-M-1} \times 2 = 2^{n-M}$

两种情况方案数相同，均为 $2^{n-M}$，因此统一乘以 $2^{n-M}$ 即可。

> **注意**：需要去重——同一个位置 $i$ 可能被 $\text{cnt}_a$ 和 $\text{cnt}_b$ 以不同方式计入，但由于我们按位置 $i$ 遍历，且 $i$ 是 LIS 的衔接点（唯一确定），因此不存在重复计数。

### 第四步：树状数组优化

求 $\text{len}_a$、$\text{cnt}_a$、$\text{len}_b$、$\text{cnt}_b$ 时，不能使用贪心+二分的 LIS 做法（因为贪心只维护一个最优解，无法统计方案数）。应使用**树状数组**维护"以值 $v$ 结尾的最长长度及方案数"。

- **正序树状数组**（求向右的 LIS）：从右向左扫描，查询 $< A[i]$ 的最大长度及方案数
- **倒序树状数组**（求向左的 LDS）：从右向左扫描，查询 $> A[i]$ 的最大长度及方案数（通过值域翻转实现）

由于值域可达 $10^9$，需要先**离散化**。

## 逐行代码解析

### 树状数组结构

```cpp
struct treearr
{
    vector<int> len;    // len[idx] = 树状数组位置 idx 处维护的最大长度
    vector<int> cnt;    // cnt[idx] = 对应的方案数
    int sz, ans_len, ans_cnt;
```

这个树状数组同时维护两个信息：**最大长度**和**对应的方案数**。与普通树状数组不同，`add` 操作不是简单累加，而是"取 max 并合并计数"。

```cpp
    void add(int idx, int num, int t_cnt)
    {
        if (num > len[idx]) len[idx] = num, cnt[idx] = t_cnt;
        else if (num == len[idx]) cnt[idx] = (cnt[idx] + t_cnt) % mod;
    }
```

- 如果新来的 `num` 更大，直接覆盖，方案数替换为 `t_cnt`
- 如果 `num` 等于当前最大，方案数累加

```cpp
    void insert(int idx, int num, int t_cnt)
    {
        while (idx <= sz)
        {
            add(idx, num, t_cnt);
            idx += lowbit(idx);
        }
    }
```

标准树状数组单点更新：沿 `idx += lowbit(idx)` 向上更新所有覆盖该位置的节点。

```cpp
    void get(int idx)
    {
        ans_len = 0, ans_cnt = 0;
        while (idx)
        {
            if (len[idx] > ans_len)
            {
                ans_len = len[idx];
                ans_cnt = cnt[idx];
            }
            else if (len[idx] == ans_len) ans_cnt = (ans_cnt + cnt[idx]) % mod;
            idx -= lowbit(idx);
        }
    }
```

前缀查询：沿 `idx -= lowbit(idx)` 向下查询 $[1, \text{idx}]$ 范围内的最大长度及方案数。同样地，遇到更长的就替换，遇到等长的就累加。

### 主函数

```cpp
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr); cout.tie(nullptr);
    int n;
    cin >> n;
    vector<int> fac(n + 1);
    fac[0] = 1;
    for (int i = 1; i <= n; i++) fac[i] = (fac[i - 1] << 1) % mod;
```

预处理 $2$ 的幂次表 `fac[i]`（即 $2^i \bmod \text{mod}$），用于后续方案数计算中的 $2^{n-M}$。

```cpp
    vector<int> A(n + 1);
    for (int i = 1; i <= n; i++) cin >> A[i];
    vector<int> tmp(A);
    sort(tmp.begin() + 1, tmp.end());
    tmp.erase(unique(tmp.begin() + 1, tmp.end()), tmp.end());
```

**离散化**：排序 + 去重，将值域从 $[1, 10^9]$ 压缩到 $[1, m]$（$m$ 为不同值的个数）。离散化后才能用树状数组维护。

```cpp
    treearr arr_a(tmp.size());  // 正序：维护向右的严格上升子序列
    treearr arr_b(tmp.size());  // 倒序：维护向左的严格下降子序列
    vector<int> len_a(n + 1), cnt_a(n + 1);
    vector<int> len_b(n + 1), cnt_b(n + 1);
```

两个树状数组分别维护两个方向：
- `arr_a`：查询 $< A[i]$ 的最大长度（向右 LIS），通过值域翻转实现"严格小于"
- `arr_b`：查询 $< A[i]$ 的最大长度（向左 LDS），直接用原值

```cpp
    for (int i = n; i >= 1; --i)
    {
        A[i] = lower_bound(tmp.begin() + 1, tmp.end(), A[i]) - tmp.begin();
        int a = tmp.size() - A[i] + 1, b = A[i];
```

**从右向左扫描**：先离散化 $A[i]$，然后计算两个查询位置：
- `a = m - A[i] + 1`：值域翻转，使得查询 `[1, a-1]` 等价于查询"值 $> A[i]$"（向左的严格下降）
- `b = A[i]`：原值，查询 `[1, b-1]` 等价于查询"值 $< A[i]$"（向右的严格上升）

```cpp
        arr_a.get(a - 1);
        len_a[i] = arr_a.ans_len + 1;
        cnt_a[i] = arr_a.ans_cnt ? arr_a.ans_cnt : 1;
        arr_a.insert(a, len_a[i], cnt_a[i]);
```

**求向左的严格下降子序列**（即翻转前缀的贡献）：
- `arr_a.get(a - 1)`：查询值 $> A[i]$ 的元素中，最大长度及方案数
- `len_a[i] = ans_len + 1`：在之前最优解基础上延伸 1
- `cnt_a[i]`：若查询结果为空（`ans_cnt == 0`），说明 $A[i]$ 是第一个，方案数为 1
- `arr_a.insert(a, ...)`：将当前元素插入树状数组

```cpp
        arr_b.get(b - 1);
        len_b[i] = arr_b.ans_len + 1;
        cnt_b[i] = arr_b.ans_cnt ? arr_b.ans_cnt : 1;
        arr_b.insert(b, len_b[i], cnt_b[i]);
    }
```

**求向右的严格上升子序列**（即原始后缀的贡献）：同理，用原值 $b = A[i]$ 查询。

```cpp
    int ans_len = 0, ans_cnt = 0;
    for (int i = 1; i <= n; i++)
    {
        int len = len_a[i] + len_b[i] - 1;
        int cnt = (((((long long)cnt_a[i] * cnt_b[i]) % mod) * fac[n - len]) % mod);
        if (len > ans_len) ans_cnt = cnt, ans_len = len;
        else if (len == ans_len) ans_cnt = (ans_cnt + cnt) % mod;
    }
    cout << ans_len << ' ' << ans_cnt;
    return 0;
}
```

**合并答案**：遍历每个位置 $i$，计算拼接后的 LIS 长度 `len = len_a[i] + len_b[i] - 1`（减 1 因为位置 $i$ 被两段各算了一次），方案数 `cnt = cnt_a[i] * cnt_b[i] * 2^(n-len)`。

取所有位置中长度最大的方案数之和。注意乘法用 `long long` 中间转换避免溢出。

## 复杂度分析

### 时间复杂度

| 操作 | 复杂度 | 说明 |
|---|---|---|
| 离散化（排序+去重） | $O(n \log n)$ | 对 $n$ 个元素排序 |
| 逆序扫描（求 len/cnt） | $O(n \log n)$ | 每个位置 2 次树状数组查询 + 2 次更新，每次 $O(\log n)$ |
| 合并答案 | $O(n)$ | 遍历所有位置 |
| **总计** | $O(n \log n)$ | 离散化 + 树状数组主导 |

### 空间复杂度

| 数据 | 空间 | 说明 |
|---|---|---|
| 离散化数组 `tmp` | $O(n)$ | 去重后的值域 |
| 两个树状数组 | $O(n)$ | 各 $n+1$ 大小的 `len` 和 `cnt` |
| DP 数组 | $O(n)$ | `len_a`, `cnt_a`, `len_b`, `cnt_b` 各 $n+1$ |
| 幂次表 `fac` | $O(n)$ | 预处理 $2^0$ 到 $2^n$ |
| **总计** | $O(n)$ | 线性空间 |

## 常见陷阱与注意事项

1. **构造转化是本题核心**
   - 题目描述的"左右放数"操作等价于"选子序列翻转后拼接"
   - 这个转化是整道题的突破口，没有这个观察无法继续

2. **不能用贪心+二分求 LIS**
   - 贪心+二分只维护最优解的末尾值，无法统计方案数
   - 必须用树状数组同时维护最大长度和方案数

3. **值域翻转技巧**
   - 求严格下降子序列时，将值 $v$ 映射为 $m - v + 1$，这样"查询 $> v$"就变成了"查询 $< (m-v+1)$"，统一用树状数组的前缀查询

4. **$A_1$ 的特殊性**
   - $A_1$ 是第一个被写入的数，它决定了"翻折"的起点
   - 方案数推导中 $A_1$ 是否属于 LIS 影响中间过程，但最终两种情况方案数相同（均为 $2^{n-M}$）

5. **离散化必须去重**
   - `sort` + `unique` 保证相同值映射到同一位置
   - 严格上升/下降要求"不等于"，离散化后用 `b - 1` / `a - 1` 查询即可

6. **乘法溢出**
   - `cnt_a[i] * cnt_b[i]` 两个 `int` 相乘可能溢出，必须先转 `long long`
   - 代码中 `((((long long)cnt_a[i] * cnt_b[i]) % mod) * fac[n - len]) % mod` 逐步取模

7. **从右向左扫描**
   - 因为我们需要"以 $i$ 结尾向左"和"以 $i$ 开头向右"的信息，而树状数组查询的是"之前已插入的元素"
   - 从右向左扫描时，已插入的是 $i$ 右边的元素，查询结果正好是"以 $i$ 为起点的向右信息"

## 对比与扩展

| 方法 | 时间 | 空间 | 能否统计方案数 | 适用场景 |
|---|---|---|---|---|
| 朴素 DP | $O(n^2)$ | $O(n)$ | 能 | 小数据，$n \le 5000$ |
| 贪心+二分 | $O(n \log n)$ | $O(n)$ | 不能 | 只需长度，不需方案数 |
| **树状数组（本算法）** | $O(n \log n)$ | $O(n)$ | **能** | 需要长度+方案数 |
| 线段树 | $O(n \log n)$ | $O(n)$ | 能 | 同树状数组，常数稍大 |

### 扩展

- **LIS 方案数问题**：本题的树状数组技巧可直接用于"求 LIS 长度及方案数"的标准问题
- **LCS 方案数**：类似的"维护最大值+计数"思路也可用于最长公共子序列方案数
- **区间 DP 中的计数**：许多需要同时维护最优值和方案数的 DP 问题都可以借鉴这种"树状数组同时维护 len 和 cnt"的技巧$AKB453$, '动态规划', array['动态规划', 'LIS', '树状数组', '离散化', '构造转化', '计数'], null, '暂未评定', 'problem'),
('world-needs-sunday', 'col-prob-csps2020-program-fill-2', 'CSP-S 2020 程序填空2 — 子序列最大异或分值（高低位分拆状压DP）', $AKB454$## 题目描述

给定 $n$ 个数（$n \le 10000$），每个数是 16 位的非负整数，即 $0 \le a_i < 2^{16} = 65536$。

要求从中选出一个**子序列**（保持原顺序，可不连续），使得分值最大。

分值的定义：子序列中每相邻两个元素做异或（XOR）运算，统计异或结果二进制中 1 的个数，把所有相邻对的 1 的个数加起来，就是总分。

形式化地，设选出的子序列为 $b_1, b_2, \ldots, b_k$，则分值为：

$$
\text{分值} = \sum_{i=1}^{k-1} \text{popcount}(b_i \oplus b_{i+1})
$$

其中 $\text{popcount}(x)$ 表示 $x$ 的二进制表示中 1 的个数。

### 输入格式

- 第一行一个正整数 $n$。
- 第二行 $n$ 个非负整数 $a_1, a_2, \ldots, a_n$。

### 输出格式

- 输出一个整数，表示最大分值。

### 数据范围

对于 $100\%$ 的数据，$n \le 10000$，$0 \le a_i < 2^{16} = 65536$。

### 提示

用高低 8 位分拆的状态压缩 DP。

## 样例

### 样例输入

```
4
3 12 0 15
```

### 样例输出

```
10
```

### 样例解释

选出全部 4 个数构成子序列 $[3, 12, 0, 15]$：

- $3 \oplus 12 = 0011_2 \oplus 1100_2 = 1111_2 = 15$，popcount = 4
- $12 \oplus 0 = 1100_2 \oplus 0000_2 = 1100_2 = 12$，popcount = 2
- $0 \oplus 15 = 0000_2 \oplus 1111_2 = 1111_2 = 15$，popcount = 4

总分：$4 + 2 + 4 = 10$。

## 解题思路

### 一、题意翻译

题目大白话：从一排数中按顺序挑一些数出来（子序列），使得两两相邻之间的"二进制差异位数"之和最大。

两个数的异或结果中有几个 1，就说明它们有几位不一样。所以"相邻一对的得分" = 两数二进制不同的位数。要让总分最高，就要让相邻的数"长得尽量不一样"——16 位全都相反的话，一对最多能拿 16 分。

### 二、朴素 DP：O(n²) —— 不够好

设 $f(i)$ 表示"以第 $i$ 个数为结尾的子序列的最大分值"。

转移：第 $i$ 个数可以接在任何一个更早的数 $j$ 后面，也可以自己单开一个子序列：

$$
f(i) = \max\!\Big(0, \max_{j < i}\big(f(j) + \text{popcount}(a_j \oplus a_i)\big)\Big)
$$

总时间复杂度 $O(n^2)$，$n=10^4$ 时约 1 亿次运算，偏紧且可扩展性差。

瓶颈在于：每次转移必须枚举"前一个数是谁"。能不能不枚举前一个数，改成枚举前一个数的**压缩信息**？

### 三、关键观察：值域小才是命门

注意每个数只有 16 位，也就是说全世界的数总共只有 65536 种。$n$ 有一万个，但种类只有六万多种。

这提示我们：别把状态建在"第几个数"上，把状态建在"数值"上。

设 $g(v)$ 表示"以值为 $v$ 的某个数结尾的最大分值"。读完一个新数 $a$，我们想对所有可能的旧值 $v$ 求：

$$
g(a) = \max\!\Big(0, \max_{v}\big(g(v) + \text{popcount}(v \oplus a)\big)\Big)
$$

但"所有旧值"有 65536 个，每次转移枚举 65536 个旧值，还是太慢。

问题卡在：转移要同时枚举旧值的 16 位，太宽了。

### 四、核心性质：异或和计数都能"按位拆"

得分的定义是异或结果中 1 的个数。异或是逐位独立运算的，"数 1 的个数"也是把每一位的 1 加起来。所以得分可以拆成两部分：

$$
\text{popcount}(p \oplus a) = \text{popcount}(p_{\text{高}} \oplus a_{\text{高}}) + \text{popcount}(p_{\text{低}} \oplus a_{\text{低}})
$$

其中 $p_{\text{高}}$ 表示 $p$ 的高 8 位，$p_{\text{低}}$ 表示 $p$ 的低 8 位。

这个朴素的等式是整道题的钥匙——得分可以拆成"高 8 位得分"和"低 8 位得分"，两笔账分开算、最后相加。

### 五、高低 8 位分拆

把每个 16 位数 $a$ 拆成两半：

- 高 8 位：$x = a \gg 8$（相当于 $a$ 整除 256）
- 低 8 位：$y = a \mathbin{\&} 255$（相当于 $a$ 除以 256 的余数）

代码中 `M = 16`，`B = 8`，`MS = 255`，就是这个意思。

这样一来，转移时可以只枚举前驱的**高 8 位**（256 种），低 8 位那部分账用别的办法处理。

### 六、"预付费"技巧

新数 $a$ 来了，它跟前驱 $p$ 的总得分是：

- 高 8 位得分：$p$ 的高 8 位 异或 $a$ 的高 8 位，数 1
- 低 8 位得分：$p$ 的低 8 位 异或 $a$ 的低 8 位，数 1

高 8 位好办：转移时枚举前驱的高 8 位 $z$（256 种），顺手就能算。

低 8 位是难点：它同时依赖"前驱的低 8 位"和"当前数的低 8 位"。如果表里只存"前驱以高 8 位 $h$ 结尾的最大分值"，那前驱的低 8 位信息就丢了，这笔账没法算。

**解决办法（预付费技巧）**：把表升级成二维的 `Max[高8位][低8位]`，含义是：

> 在所有已经出现过、且高 8 位等于 $h$ 的数 $p$ 中，取 "$p$ 为结尾的最大分值 $+$ $p$ 的低 8 位与 $l$ 异或后 1 的个数" 的最大值。

翻译成人话：假如下一个数的低 8 位是 $l$，而之前有个高 8 位为 $h$ 的前驱 $p$，那么把 $p$ 和这个未来数之间的**低 8 位得分先预支**、加在 $p$ 的分值上，最多能攒到多少分。

要点：
- 预付的账（$p$ 的低 8 位 异或 $l$）是按 $l$ 的取值分别存好的——$l$ 只有 256 种，所以每种可能的"未来低 8 位"都各存了一份
- 如果高 8 位为 $h$ 的数还一个都没出现过，`Max[h][l]` 就是负无穷，表示"查无此人，不许转移"

### 七、转移流程

新数 $a$ 到来，设它的高 8 位是 $x$、低 8 位是 $y$。

**第一步（查询）**：枚举前驱的高 8 位 $z$（共 256 种），算以 $a$ 结尾的最大分值 $v$：

$$
v = \max\!\Big(0, \max_{0 \le z \le 255}\big(\text{Max}[z][y] + \text{popcount}(x \oplus z)\big)\Big)
$$

其中 `Max[z][y]` 里已经包含了"前驱分值 + 前驱与 $a$ 之间的低 8 位得分"，再加上高 8 位得分，就是完整的转移得分。

$v$ 的初值是 $0$，含义是"$a$ 自己单开一个子序列，得分 0"。

**第二步（更新）**：把 $a$ 自己也"预付费"地写进表里。枚举未来数的低 8 位 $z$（共 256 种）：

$$
\text{Max}[x][z] = \max\!\big(\text{Max}[x][z],\ v + \text{popcount}(y \oplus z)\big)
$$

这里预付的账是"$a$ 的低 8 位与未来数的低 8 位 $z$ 的异或得分"。

**第三步**：全局答案 `ans` 取 `ans` 和 `v` 中较大者。

### 八、为什么这样不会算重、不会算漏

**不会算漏**：任何最优子序列，考虑它的最后一对相邻数 $p$ 和 $a$。$p$ 被处理时，它的分值带着"对 $a$ 的低 8 位的预付费"存进了 `Max[p高8位][a低8位]`（因为更新时 $z$ 枚举了全部 256 种，一定覆盖 $a$ 的低 8 位）。$a$ 处理时查询 $z = p$ 的高 8 位，把高 8 位的账补上，加出来正好是完整分值。

**不会算重**：每个相邻对的得分恰好被拆成低 8 位（预付时算）+ 高 8 位（查询时算）两笔，各算一次，不重不漏。

**取 max 天然正确**：同一个 $(h, l)$ 格子里如果有很多前驱，存最大值即可，转移时取到的自动就是最优的那个。

### 九、初始化与边界的两个"坑"

**坑一：Max 表必须初始化成负无穷，不能是 0。**

0 会被理解成"存在一个分值为 0 的前驱"，但开局谁都没出现过。用 0 会导致凭空多出转移、答案虚高。负无穷表示"这一格无效"，配合取 max 就自动被忽略。

**坑二：v 的初值必须是 0，不能是负无穷。**

因为只选一个数也是合法子序列，分值是 0。如果 v 从负无穷起步而表里全是负无穷，v 就永远是负无穷，一个数都不选的错误就会发生。

代码里 `INF` 取 $10^{15}$ 这么大，是因为分值最大约 $n \times 16$（一万个数、每对最多 16 分），负无穷要"负得足够多"才不会被当真。

### 十、手算验证（缩小版）

16 位太大不好手算，我们做一个缩小版：4 位拆 2+2，思想一模一样。此时 `MS = 3`，表是 4×4 的。

输入序列：$3, 12, 0, 15$，写成 4 位二进制并拆开：

| 数 | 二进制 | 高 2 位 x | 低 2 位 y |
|----|--------|----------|----------|
| 3 | 0011 | 0 | 3 |
| 12 | 1100 | 3 | 0 |
| 0 | 0000 | 0 | 0 |
| 15 | 1111 | 3 | 3 |

流程：

1. **处理 3（x=0, y=3）**：Max 全是负无穷，v = 0（单干）。更新 Max[0][z] = 0 + popcount(3 ⊕ z)。得 Max[0] = [2, 1, 1, 0]。
2. **处理 12（x=3, y=0）**：查询 Max[z][0]，只有 Max[0][0]=2 有效。v = 2 + popcount(3 ⊕ 0) = 2 + 2 = 4。对应子序列 [3, 12]，得分 4。更新 Max[3][z] = 4 + popcount(0 ⊕ z)，得 [4, 5, 5, 6]。
3. **处理 0（x=0, y=0）**：查询 Max[z][0]，Max[0][0]=2、Max[3][0]=4。v = max(2+0, 4+2) = 6。对应子序列 [3, 12, 0]，得分 6。更新 Max[0][z] = 6 + popcount(0 ⊕ z)，得 [6, 7, 7, 8]。
4. **处理 15（x=3, y=3）**：查询 Max[z][3]，Max[0][3]=8、Max[3][3]=6。v = max(8+2, 6+0) = 10。对应子序列 [3, 12, 0, 15]，得分 10。

最终答案 10，与样例输出一致。

### 十一、复杂度分析

| 维度 | 复杂度 | 说明 |
|---|---|---|
| 时间 | $O(n \cdot 2^B)$ | 每个数查询 256 次 + 更新 256 次，共 $n \times 512$ |
| 空间 | $O(2^{2B})$ | $256 \times 256$ 个 long long，约 0.5 MB |

总计约 500 多万次运算，瞬间跑完。对比朴素 DP 的 1 亿次，优化效果显著。核心原因：把"枚举前驱的 16 位"拆成了"预付低 8 位 + 枚举高 8 位"，枚举量从 $2^{16}$ 降到了两次 $2^8$。

### 十二、一句话提炼

当转移代价依赖于"前驱值"和"当前值"的两部分、且每部分都能按位独立计算时，可以把值域拆成高低两半：把涉及"前驱低半段 × 当前低半段"的那笔代价，提前按当前低半段的每一种取值预付并存进二维表；转移时只需枚举前驱的高半段。枚举量从"两半的乘积"降到"两半各自"，这正是"状态压缩 + 代价前移"的经典组合拳。

