## 解题思路

### 题目在问什么

一堆作业只能从上往下拿，一次最多带 $w$ 本；每趟从讲台（位置 $0$）出发沿路把作业发到同学们的位置上，可以随时回讲台补货；最后一趟发完不必回讲台。求总行走距离最小。

### 思路从哪来：看到 $w \le 5$ 就该想到状压

看到 $w \le 5$，就知道状态里可以塞下「手里拿的这几本作业分别是谁的」。

再看 $n \le 24$：每个同学编号可以用 $5$ 个二进制位存下（$2^5 = 32 > 24$），$w$ 本作业就是 $5w \le 25$ 位，刚好压进一个 `int`。两个上界一凑，这就是一道标准的**状态压缩 + 记忆化搜索**。

状态设计的关键：**手里拿的作业是哪几本，以及已经处理到第几本作业**。

### 状态定义

用 `dfs(i, state)` 表示：

- 已经处理完前 $i$ 本作业（即第 $1 \sim i$ 本已经取走或分发掉）；
- 当前手里还拿着若干本作业，这些作业对应的同学编号被压缩在 `state` 中（每本用 $5$ 位编码，按从高到低排列）；
- 返回**从当前状态开始，发完剩余所有作业所需的最短额外距离**。

编码方式：`state` 中每 $5$ 位存一个同学编号（$1 \sim n$），不足 $w$ 本时低位补 $0$。例如 `state = (x1 << 5*(w-1)) | (x2 << 5*(w-2)) | ...`，其中 $x_i$ 表示第 $i$ 本作业的目标同学。因为 $w$ 个槽位里装的其实是**一个多重集合**，代码里统一按**降序**排列后再编码，保证同一个集合只有一种编码。

因为状态空间可能很大，原笔记用 `map<int, i64>` 做记忆化。

### 转移方程

在 `dfs(i, state)` 中，先解码出当前手里各本作业的目标同学，记作数组 `x[1..w]`（空位为 $0$）。

**递归基**：如果 `i == m`，所有作业都已取走，此时只需要把手里的作业全部发掉；因为最后不用回讲台，所以代价是这些作业中最大的同学编号（走到最远的那个，沿途全都顺手发了）。即

$$
\text{ans} = \max_{1 \le j \le w} x_j
$$

（如果手里为空，则返回 $0$。）

否则，有两种决策：

1. **再拿一本新作业**（前提是手里还没满 $w$ 本）：从第 $i+1$ 本作业取走，加入手中。设当前已拿数量为 `cnt`（非零元素个数），若 `cnt < w`，则把 `a[i+1]` 放进手里再排序压缩，然后递归到 `dfs(i+1, state')`。这一趟取作业是在讲台上完成的，**不花行走距离**。

2. **发掉某一类作业**：选择当前手中存在的一个目标 $d$（即某个非零的 $x_j$），从讲台出发走到位置 $d$ 再返回讲台，代价 $2d$。走到 $d$ 的路上会经过 $1,2,\dots,d$，所以**所有目标 $\le d$ 的作业都能顺路发掉**；发完后手里只保留目标 $> d$ 的作业，递归：

$$
dfs(i, state) = \min_{d \in \text{hand}} \left( 2d + dfs(i, state_{\text{remove } \le d}) \right)
$$

   注意这里递归时 `i` 不变，因为只是发掉了手里的作业，并没有取新的作业。

最终答案就是 `dfs(0, 0)`，一开始手里没作业。

### 为什么这样设计是合法的

- 每次从讲台出发去发一批作业，回来再取下一批，符合「可以随时回讲台」的规则。
- 最后一次不用回讲台，已经在递归基中特殊处理：只取最大距离，不加返回的 $2d$。
- 拿作业的顺序被限制为从上往下，所以 `i` 单调递增，不会出现逆序。
- 因为 $w$ 很小，手里带的作业数量有限；每次发作业时把能顺路的一起发是最优的（分开跑两趟只会多走路），所以「走到 $d$ 就发掉所有 $\le d$ 的」不会漏掉更优解。

### 一点小彩蛋

原笔记说：这是出题人 GOC 出的第一道题，作为月赛投题。核心就是状态压缩 + 记忆化搜索，如果你能把它想通，状压 DP 的基本功就算过关了！

## 逐行代码解析

### 模块一：头文件与读入

```cpp
#include <bits/stdc++.h>

using i64 = long long;

void solve(void) {
    int n, m, w;
    std::cin >> n >> m >> w;
    std::vector<int> a(m + 1);
    for (int i = 1; i <= m; i++) std::cin >> a[i]; // a[i]：自上而下第 i 本作业的目标同学
```

- `i64` 是 `long long` 的别名；总距离累加可能较大，用 64 位整数。
- `a` 从 $1$ 开始编号，正好对应「第 $i$ 本」；下标 $0$ 空着不用。
- 全部逻辑收进 `solve`，方便以后改成多测。

### 模块二：编码函数、记忆化表与解码

```cpp
    auto get = [&](std::vector<int> &x) -> int { // 把 w 个目标打包进一个 int
        int res = 0;
        for (int i = 1; i <= w; i++) res |= (x[i] << (5 * (w - i)));
        return res;
    };

    std::vector<std::map<int, i64>> f(m + 1); // 按进度 i 分桶的记忆化表
    auto dfs = [&](auto && self, int i, int c) -> i64 {
        if (f[i].count(c)) return f[i][c]; // 算过就直接返回
        std::vector<int> x(w + 1);
        for (int i = 1; i <= w; i++) x[i] = (c >> (5 * (w - i))) & 31; // 解码：每 5 位取一个编号
```

- `get` 把 `x[1..w]` 从高位到低位依次摆放，每本占 $5$ 位；`& 31` 就是取低 $5$ 位（$31 = 2^5 - 1$），编码与解码严格互逆。
- `f` 按进度分桶：`f[i]` 只存「已处理到第 $i$ 本」的那些状态，避免把 $i$ 和编码混进一个键。
- 解码循环里的 `int i` **遮住了外层参数 `i`**（作用域只在这个 for 里），功能上没问题，但读代码时容易看花眼。

### 模块三：递归基与「再拿一本」

```cpp
        if (i == m) {
            return f[i][c] = *std::max_element(x.begin() + 1, x.end()); // 最后一趟只走单程
        }

        i64 ans = 1e18;
        int s = 0;
        for (int i = 1; i <= w; i++) {
            //if ((c >> (5 * i)) & 31) s++;
            if (x[i]) s++; // 统计手里现有的本数
        }

        if (s < w) {
            std::vector<int> b(w + 1);
            for (int j = 1; j <= w; j++) b[j] = x[j];
            b[s + 1] = a[i + 1]; // 新拿的一本放进第一个空位
            std::sort(b.begin() + 1, b.end(), std::greater<int>()); // 降序规范化
            ans = std::min(ans, self(self, i + 1, get(b)));
        }
```

- `i == m` 时作业全取完了，`max_element(x[1..w])` 就是「走到最远那位同学」的单程距离；手里空时最大值是 $0$。
- `s` 数的是非零槽位数。因为维护了降序，非零值一定挤在 `x[1..s]`，所以新书放到 `b[s+1]` 再排序即可。
- 降序排序是这个写法的**隐形不变量**：去重（相邻相等）和「删掉 $\le d$」都依赖它。
- `1e18` 只是「还没找到可行解」的哨兵，配合 `min` 使用。
- `//if ((c >> (5 * i)) & 31) s++;` 是留下的一行注释，位偏移写错了（多乘了一个 $5$），已经不用了。

### 模块四：发掉一批作业

```cpp
        for (int j = 1; j <= w; j++) {
            int d = x[j];
            if (d == 0) continue; // 空位跳过
            if (j > 1 && x[j] == x[j - 1]) continue; // 同一目标只枚举一次
            std::vector<int> b(w + 1);
            int idx = 1;
            for (int k = 1; k <= w; k++) {
                if (x[k] > d) b[idx++] = x[k]; // 只保留比 d 更远的，其余顺路发掉
            }
            ans = std::min(ans, (i64)2 * d + self(self, i, get(b)));
        } 

        return f[i][c] = ans;
    };
```

- `d == 0` 是空槽，跳过；`x[j] == x[j-1]` 说明这个目标已经枚举过，跳过避免重复搜索。
- `if (x[k] > d)` 保留严格大于 $d$ 的，等于 $d$ 的和更近的都被这一趟顺路发掉——这就是「走到 $d$ 沿途分发」的编码实现。
- 代价 `(i64)2 * d`：先转 64 位再乘，避免 `int` 溢出；递归时 `i` 保持不变。
- 最后 `f[i][c] = ans` 把结果写回记忆化表。

### 模块五：输出与主函数

```cpp
    std::cout << dfs(dfs, 0, 0); // 初始：一本没取、手里为空
}

int main(void) {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int t = 1;
    //std::cin >> t;
    while (t--) solve();

    return 0;
}
```

- 答案就是 `dfs(0, 0)`。
- 关同步、解绑输入输出是常规加速；`t` 固定为 $1$，注释掉的那行随时可以改成多测。

## 复杂度分析

- **时间复杂度**：状态数形式上是 $O\big(m \times (n+1)^w\big)$（进度 $0\sim m$，状态是 $w$ 个 $5$ 位块），但这是很松的上界——实际可达状态远少于它：手里最多 $w$ 本、每本只能是 $1\sim n$，还要受「从上往下拿」的进度约束。单次转移需要解码 $O(w)$，发作业分支最多枚举 $w$ 个去重目标并重建状态 $O(w)$，即 $O(w^2)$。对 $m \le 1000$、$w \le 5$ 来说运行飞快。
- **空间复杂度**：$O\big(m \times (n+1)^w\big)$，即 `std::map` 记忆化表的总规模；同样受「可达状态远小于上界」的约束，实际很小。

## 常见陷阱与注意事项

1. **$5$ 位编码是用 $n \le 24$ 换来的**：$2^5 = 32 > 24$，所以每个编号刚好放得下；一旦 $n \ge 32$，编号会溢出 5 位块，压缩和解码互相污染，必须把位宽改成 $\lceil \log_2 n \rceil$ 并同步改掩码 `& 31`。
2. **降序不变量的维护**：新书是「丢到 `b[s+1]` 再整体排序」，删除分支是「只保留 $>d$ 的、按原序前移」。两处都保持降序，才有了「非零值挤在前 `s` 个槽位」和「相邻相等可去重」这两条便利；若改成乱序，`b[s+1]` 会覆盖掉有效数据。
3. **删的是 $\le d$，不是 $= d$**：这一趟走到 $d$ 会把沿途所有更近的作业一并发掉，误写成「只删等于 $d$」就会漏掉这项免费优化，答案偏大。
4. **递归基只能走单程**：`i == m` 时返回 $\max x_j$ 而不是 $2\max x_j$；忘记「最后不用回讲台」多乘个 $2$，直接 WA。
5. **拿书分支的边界**：`b[s+1] = a[i+1]` 只在 `i < m` 时执行（`i == m` 已提前返回），`s < w` 保证 `s+1 <= w` 不越界；把 `s < w` 写成 `s <= w` 就会写穿。
6. **记忆化键要带进度**：这里用 `vector<map<int,i64>> f(m+1)` 按 $i$ 分桶。若把 $i$ 和编码揉进同一个 `int` 键，两维信息可能撞车，务必分开或换成能区分两维的键。
7. **局部变量遮住外层 `i`**：解码循环和计数循环都写了 `for (int i = ...)`，和外层参数同名。C++ 里合法且不影响结果（出了 for 作用域就恢复），但极容易在改动时误伤，读代码时要看清。

## 对比与扩展

- **与旅行商 / 邮递员问题的关系**：这类「从原点出发访问若干目标求最短路」天然是 TSP 风格；但本题所有目标都在一条直线 $1\sim n$ 上，且可以反复回原点，于是「走到 $d$ 就顺路覆盖 $1..d$」这条一维几何性质，把「枚举访问顺序」的指数级搜索压成了「只决定这一趟走多远」。
- **状压 + 进度的通用套路**：当「需要保留的小集合」和「一个单调推进的进度」都能塞进状态时，就可以写成 `dfs(进度, 压缩集合)` 的记忆化搜索；「编号 $\le 2^k$ 的元素用 $k$ 位打包」这个技巧适用于任何元素编号较小的场景。
- **参数再大一点的走向**：$w \le 5$ 是状压可行的关键。若 $w$ 或 $n$ 显著增大，状态空间会爆炸，通常得换思路（例如按「最后一次回讲台」划分的区间 DP，或把往返次数建成费用流）。
- **变式**：如果要求「发完必须回到讲台」，只需把递归基的 $\max x_j$ 改成 $2\max x_j$，其余逻辑不动。$AKB455$, '动态规划', array['状态压缩', '记忆化搜索', '动态规划', '位运算'], null, '暂未评定', 'problem'),
('Fohen', 'col-prob-goc-homework', '发作业', $AKB456$## 题目描述

有 $n$ 个同学排成一列，位置依次为 $1 \sim n$，讲台在位置 $0$。有 $m$ 本作业堆成一摞，只能**从上往下**逐本拿取，第 $i$ 本作业属于同学 $a_i$。

GOC 一次最多携带 $w$ 本作业（$w \le 5$），他可以随时回讲台取下一批作业，沿路分发；发完全部作业后**最后不必回到讲台**。求发完所有作业的**最短总行走距离**。

### 输入格式

题面未给出显式的输入格式说明；依据所附代码，输入共两行：

- 第一行三个整数 $n,m,w$，分别表示同学数、作业本数、一次最多携带的本数；
- 第二行 $m$ 个整数 $a_1,a_2,\dots,a_m$，依次表示自上而下第 $i$ 本作业归属的同学编号。

### 输出格式

题面未给出显式的输出格式说明；依据所附代码，输出一行一个整数，表示发完所有作业的最短总行走距离。

### 数据范围

- $n \le 24$，$m \le 1000$，$w \le 5$；
- 同学编号 $a_i$ 满足 $1 \le a_i \le n$（由「第 $i$ 本作业属于同学 $a_i$」可直接得出）。

## 样例

官方样例未取得。

## 解题思路

看到 $w \le 5$，第一个念头是：**手里这一摞作业的目标集合很小，可以整个塞进状态**；再看 $n \le 24 < 2^5$，每个同学编号恰好能用 $5$ 个二进制位编码，于是 $w$ 本作业最多 $5w \le 25$ 位，压进一个 `int` 绰绰有余。这就是「状态压缩 + 记忆化搜索」的入口。

### 关键性质：沿路分发

问题的核心动作是「从讲台（位置 $0$）走到某个位置 $d$，再返回讲台」。这一趟往返的代价是 $2d$，而途中会依次经过位置 $1,2,\dots,d$——也就是说，**只要手里有目标 $\le d$ 的作业，这一趟都能顺路发掉，不必额外绕路**。于是决策退化成「选一个最远的落点 $d$」，代价只由 $d$ 决定，与手里具体发几本无关。

### 状态定义

用 `dfs(i, state)` 表示：已经处理完前 $i$ 本作业（第 $1 \sim i$ 本已被取走或分发），当前手里还拿着若干本作业，这些作业的目标编号被压缩在 `state` 里（每本占 $5$ 位，按从高到低排列，空位为 $0$）。函数返回**从当前局面出发，发完剩余所有作业还需要的最短额外距离**。

编码方式：`state` 从高到低第 $j$ 个 5 位块存同学编号 $x_j$，即 `state = (x[1] << 5*(w-1)) | (x[2] << 5*(w-2)) | ...`（具体顺序无所谓，只要能唯一表示「手里拿着哪个多重集合」即可）。用 `std::map<int, i64>` 对每个进度 $i$ 做记忆化。

### 转移方程

设 $x[1..w]$ 为解码出的目标数组（非零值按降序排列，空位为 $0$）。

**递归基**（$i = m$）：所有作业都已取走，只需把手里剩下的全部发掉。因为最后不用回讲台，只走一趟，代价就是最远目标的位置：

$$
dfs(m, state) = \max_{1 \le j \le w} x_j
$$

（手里为空时最大值是 $0$，代价为 $0$。）

**决策一 · 再拿一本**（手里不足 $w$ 本且 $i < m$）：把第 $i+1$ 本作业加入手中，不产生行走代价：

$$
dfs(i, state) \to dfs(i+1, state')
$$

其中 $state'$ 是把 $a_{i+1}$ 插入手中后重新排序压缩的结果。

**决策二 · 发掉一批**：枚举手里出现的某个目标 $d$，从讲台出发走到 $d$ 再回来（代价 $2d$），顺路发掉**所有目标 $\le d$ 的作业**，手里只保留目标 $> d$ 的：

$$
dfs(i, state) = \min_{d \in \text{hand}}\Big(2d + dfs\big(i,\, state'\big)\Big)
$$

其中 $state'$ 是删去所有目标 $\le d$ 的作业后得到的新状态。注意递归时 $i$ 不变——这一决策只发书、不取新书。

最终答案为 $dfs(0, 0)$（还没取书、手里为空）。

### 为什么这样做是对的

- **每次出发都回讲台**：除最后一次外，每次「走到 $d$ 再回来」恰好对应一次往返，符合「可以随时回讲台取下一批」的规则；最后一次已在递归基里特殊处理，只走单程。
- **拿书顺序单调**：只能从上往下拿，所以「已处理到第 $i$ 本」这个进度只会单调前进；决策二不动 $i$，决策一让 $i$ 加一，任何合法发书序列都能被这棵搜索树枚举到。
- **顺路一次发掉不更贵**：$w$ 很小，手里书不多；若把同一个目标 $d$ 分两趟发，两趟都要走到 $d$，总代价至少 $4d$，而一趟发完只需 $2d$。更一般地，走到 $d$ 时把途中所有目标 $\le d$ 的作业一并发掉，不会比分开走更贵，因此「顺路一次发掉」不会漏掉更优解。
- **编码无冲突**：$n \le 24 < 2^5$，每个编号占满 $5$ 位互不重叠；$5w \le 25$ 位不会溢出 `int`，压缩与解码是一一对应的。

## 逐行代码解析

### 模块一：入口与读入

```cpp
#include <bits/stdc++.h>

using i64 = long long;

void solve(void) {
    int n, m, w;
    std::cin >> n >> m >> w;
    std::vector<int> a(m + 1);
    for (int i = 1; i <= m; i++) std::cin >> a[i]; // 读入自上而下每本作业的目标同学
```

- `i64` 是 `long long` 的别名，距离累加可能较大，用 64 位整数保险。
- `a` 下标从 $1$ 开始，`a[i]` 就是自上而下第 $i$ 本作业归属的同学。
- 全部逻辑收进 `solve`，配合 `main` 里的 `while (t--)` 循环，方便将来扩展多测。

### 模块二：编码函数、记忆化表与递归基

```cpp
    auto get = [&](std::vector<int> &x) -> int { // 把 w 个目标打包进一个 int
        int res = 0;
        for (int i = 1; i <= w; i++) res |= (x[i] << (5 * (w - i)));
        return res;
    };

    std::vector<std::map<int, i64>> f(m + 1); // 按进度 i 分桶的记忆化表
    auto dfs = [&](auto && self, int i, int c) -> i64 {
        if (f[i].count(c)) return f[i][c]; // 已算过直接返回
        std::vector<int> x(w + 1);
        for (int i = 1; i <= w; i++) x[i] = (c >> (5 * (w - i))) & 31; // 解码：每 5 位一个编号
        if (i == m) {
            return f[i][c] = *std::max_element(x.begin() + 1, x.end()); // 全部取完：最后一趟不用回讲台
        }
```

- `get` 把 `x[1..w]` 从左到右依次放到高位到低位，每个占 $5$ 位；`& 31` 就是取低 $5$ 位（$31 = 2^5 - 1$），与编码一一对应。
- `f` 是「按进度分桶」的记忆化表：`f[i]` 只存进度为 $i$ 的那些状态，避免把 $i$ 和状态编码混在一个键里。
- 递归基 `i == m` 时所有作业已取走，返回手里最远目标的编号 `max_element(x[1..w])`，即单程距离；手里为空时最大值是 $0$。

### 模块三：决策一 · 再拿一本作业

```cpp
        i64 ans = 1e18;
        int s = 0;
        for (int i = 1; i <= w; i++) {
            //if ((c >> (5 * i)) & 31) s++;
            if (x[i]) s++; // 统计手里非空位（已携带本数）
        }

        if (s < w) { // 手里没满，可以再拿一本
            std::vector<int> b(w + 1);
            for (int j = 1; j <= w; j++) b[j] = x[j];
            b[s + 1] = a[i + 1]; // 把下一本放入当前空位
            std::sort(b.begin() + 1, b.end(), std::greater<int>()); // 降序规范化，相同目标相邻
            ans = std::min(ans, self(self, i + 1, get(b)));
        }
```

- `ans = 1e18` 是「尚未找到可行解」的哨兵，配合 `min` 完成取最小。
- `s` 统计手里非零位的个数（即当前携带本数），只有 `s < w` 才允许再拿。
- 拿书后 `i` 加一、距离不加（在讲台取书不花行走），并把新状态降序排序——排序是后面去重与「删掉 $\le d$」两步正确性的前提。

### 模块四：决策二 · 发掉一批作业

```cpp
        for (int j = 1; j <= w; j++) {
            int d = x[j];
            if (d == 0) continue; // 空位跳过
            if (j > 1 && x[j] == x[j - 1]) continue; // 去重：同一目标只枚举一次
            std::vector<int> b(w + 1);
            int idx = 1;
            for (int k = 1; k <= w; k++) {
                if (x[k] > d) b[idx++] = x[k]; // 顺路发掉所有目标 <= d，只保留 > d
            }
            ans = std::min(ans, (i64)2 * d + self(self, i, get(b))); // 往返代价 2d，i 不变
        }

        return f[i][c] = ans;
    };
```

- 降序排列保证相同目标相邻，`x[j] == x[j - 1]` 即可跳过重复值，每个不同目标只枚举一次。
- `if (x[k] > d)` 保留严格大于 $d$ 的、丢掉 $\le d$ 的——这正是「走到 $d$ 时顺路发掉所有更近同学」的编码实现。
- 决策二递归时 `i` 不变（只发书、不取新书），往返代价固定为 $2d$；`(i64)2 * d` 先转成 64 位再相乘，避免 `int` 溢出。

### 模块五：输出与主函数

```cpp
    std::cout << dfs(dfs, 0, 0); // 初始：还没取书、手里为空
}

int main(void) {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int t = 1;
    //std::cin >> t;
    while (t--) solve();

    return 0;
}
```

- 答案就是 `dfs(0, 0)`：进度为 $0$、手里为空，从这出发发完所有作业的最短额外距离。
- 关同步、解绑输入输出，是常规加速；`t` 固定为 $1$，保留注释掉的读入可随时改多测。

## 复杂度分析

- **时间复杂度**：状态总数为 $O\big(m\cdot(n+1)^w\big)$（进度维 $0 \sim m$，状态是 $w$ 个 $5$ 位块的压缩编码，每块取值 $0 \sim n$）。这是很松的上界，实际可达状态远少于它——手里最多 $w$ 本、每本目标只能落在 $1 \sim n$，还要受「从上往下拿」的进度约束。单次转移需解码 $O(w)$、决策二枚举至多 $w$ 个去重目标并重建 $O(w)$，合计 $O(w^2)$。对 $m \le 1000$、$w \le 5$ 完全可行。
- **空间复杂度**：$O\big(m\cdot(n+1)^w\big)$，即 `std::map` 记忆化表的总规模，同样受「可达状态远小于上界」的约束。

## 常见陷阱与注意事项

1. **5 位编码依赖 $n$ 的上界**：每本用 $5$ 位是因为 $n \le 24 < 2^5$；若 $n$ 升到 $\ge 32$，编号会占满并溢出 5 位块，压缩与解码互相污染，必须把位宽改成 $\lceil\log_2 n\rceil$，并同步改掩码 `& 31`。
2. **决策二删的是 $\le d$，不是 $= d$**：`if (x[k] > d)` 保留严格大于 $d$ 的，即顺路把 $\le d$ 的都发掉；若误写成「只删等于 $d$」，会漏掉「顺路发更近同学」这项免费优化，答案偏大。
3. **降序排序是去重正确性的前提**：`if (j > 1 && x[j] == x[j-1]) continue;` 靠相邻相等去重，只有先 `sort(..., greater<int>())` 保证降序，相同目标才会相邻；否则同一目标可能被重复枚举（虽不导致错误，但徒增状态）。
4. **递归基只走单程**：$i = m$ 时返回 $\max x_j$ 而不是 $2\max x_j$；若忽略「最后不用回讲台」这条规则多乘 $2$，会直接 WA。
5. **拿书分支的边界**：决策一读 `a[i+1]` 仅在 $i < m$ 时发生（$i = m$ 已提前返回）；`s < w` 保证 `b[s+1]` 不越界。若把递归基提前返回删掉，或把 `s < w` 误写成 `s <= w`，都会访问到 `a[m+1]` 或 `b[w+1]`。
6. **记忆化键要区分进度**：这里用 `vector<map<int,i64>> f(m+1)` 按 $i$ 分桶；如果把 $(i, c)$ 混进同一个 `int` 键，$i$ 与压缩编码可能冲突，务必分开或使用能区分两维的键。

## 对比与扩展

- **与旅行商 / 邮递员问题的关系**：这类「从一个点出发访问若干目标求最短路」天然是 TSP 风格；但本题所有目标都在一条直线 $1 \sim n$ 上，且可反复回原点，于是「访问到 $d$ 就顺路覆盖 $1..d$」这条一维几何性质，把「选点集顺序」的指数枚举压缩成「只决定最远落点 $d$」。
- **状态压缩 DP 的通用套路**：当「需要保留的一个小集合」加「一个单调推进的进度」都能塞进状态时，就可用 `dfs(进度, 压缩集合)` 记忆化；本题「编号 $\le 2^k$ 的元素用 $k$ 位打包」的技巧，可推广到任何元素编号较小的场景。
- **参数再大一点的走向**：本题 $w \le 5$ 是状压可行的关键；若 $w$ 或 $n$ 显著增大，状态空间会爆炸，通常要换思路（例如按「最后一次回讲台」划分的区间 DP，或最小化往返次数的费用流建模）。
- **变式**：若去掉「最后不用回讲台」、要求必须回到讲台，只需把递归基的 $\max x_j$ 改为 $2\max x_j$，其余逻辑不变。$AKB456$, '动态规划', array['状态压缩', '记忆化搜索', '动态规划', '位运算'], null, '暂未评定', 'problem'),
('Xesir', 'col-prob-luogu-p1352--xesir', 'P1352 没有上司的舞会（Xesir 版） · Xesir', $AKB457$## 题目描述

某大学有 $n$ 个职员，编号为 $1\dots n$。他们之间有从属关系，也就是说他们的关系就像一棵以校长为根的树，父结点就是子结点的直接上司。

现在有个周年庆宴会，宴会每邀请来一个职员都会增加一定的快乐指数 $r_i$，但是，如果某个职员的直接上司来参加舞会了，那么这个职员就无论如何也不肯来参加舞会了。

请你计算，邀请哪些职员可以使快乐指数最大，求最大的快乐指数。

### 输入格式

第一行是一个整数 $n$。

第 $2$ 到第 $(n+1)$ 行，每行一个整数，第 $(i+1)$ 行的整数表示 $i$ 号职员的快乐指数 $r_i$。

第 $(n+2)$ 到第 $2n$ 行，每行输入一对整数 $l,k$，代表 $k$ 是 $l$ 的直接上司。

### 输出格式

输出一行一个整数，代表最大的快乐指数。

### 数据范围

对于 $100\%$ 的数据，$1\le n\le 6\times 10^3$，$-128\le r_i\le 127$，$1\le l,k\le n$，且给出的关系一定是一棵树。

## 样例

### 样例 1

**输入：**

```
7
1
1
1
1
1
1
1
1 3
2 3
6 4
7 4
4 5
3 5
```

**输出：**

```
5
```

**解释：** 选择职员 $1,2,3,6,7$（或等价的合法方案）可以获得最大快乐指数 $5$；不能同时选择直接上下级。

## 解题思路


### 模型与状态设计
树形 DP 是在树上做动态规划：利用树的递归结构，**先算子树，再合并到父节点**，天然适合处理「依赖关系」「覆盖问题」「子树统计」等场景。通用套路可以概括成三点：

- **状态定义**：以节点为状态维度，记录该节点或子树的一些信息。
- **计算顺序**：自底向上，DFS 后序遍历——先算完所有儿子，再合并到父亲。
- **转移**：合并子树的 DP 值，得到当前节点的 DP 值。

基本框架长这样：

```cpp
void dfs(int u, int fa) {
    // 初始化 dp[u]（视题目而定）
    for (int v : G[u]) {
        if (v == fa) continue;
        dfs(v, u);
        // 用 dp[v] 更新 dp[u]
    }
}
```

本例「没有上司的舞会」是树形 DP 的基础例题，本质是**树上的最大权独立集**：一棵树代表公司层级，每个节点有权值（快乐值），约束是「选了某节点就不能选它的直接下属」，目标是选中节点的权值和最大。

注意源程序的建边方式：输入的是 (下属 `l`, 上司 `k`)，代码执行 `bo[k].push_back(l)`，即只保留了「上司 → 下属」这一个方向，所以递归时不需要判父节点。树根就是入度为 0 的那个点，代码用 `v[l]=1` 标记「`l` 有上司」来把它找出来。

## 核心公式 / 状态定义与转移方程

状态定义：

- `dp[u][0]`：不选 $u$ 时，以 $u$ 为根的子树内的最大权值和。
- `dp[u][1]`：选 $u$ 时，以 $u$ 为根的子树内的最大权值和。

转移方程（不选 $u$）：每个儿子 $v$ 可选可不选，取较优值累加。

$$dp[u][0] = \sum_{v \in children(u)} \max(dp[v][0], dp[v][1])$$

转移方程（选 $u$）：儿子都不能选，只能取 `dp[v][0]`。

$$dp[u][1] = val[u] + \sum_{v \in children(u)} dp[v][0]$$

初始化：进入节点时 `dp[x][0]=0`、`dp[x][1]=h[x]`。最终答案 $\max(dp[root][0], dp[root][1])$。

## 逐行代码解析

### 头文件与全局变量

```cpp
#include <bits/stdc++.h>
using namespace std;
vector<int> bo[6010];
int h[6010],f[6010][2],v[6010];
```

- `bo[k]` 存上司 `k` 的所有直接下属（邻接表）；`h[i]` 是快乐值；`f[i][0]`、`f[i][1]` 即上面的两态 `dp`。
- `v[i]` 标记 `i` 是否为某人的下属（即 `i` 有没有上司），用来找唯一的根。

### dp 函数：自底向上合并子树

```cpp
void dp(int x){
    f[x][0]=0;f[x][1]=h[x];
    for(int i=0;i<bo[x].size();i++){
        int y=bo[x][i];
        //cout<<y<<" "<<x<<endl;
        dp(y);//TODO
        f[x][0]+=max(f[y][0],f[y][1]);
        f[x][1]+=f[y][0];
    }
}
```

- 先初始化两个状态：不选 `x` 得 0，选 `x` 先累加自身权值 `h[x]`。
- 遍历每个儿子 `y`，先 `dp(y)` 递归——必须先把儿子的值算好，才能合并到父亲。
- 不选 `x` 时累加 `max(f[y][0], f[y][1])`；选 `x` 时累加 `f[y][0]`（儿子不能同时选）。
- 代码行尾那两处待办注释是源笔记的自我提醒残留，照搬不改；`//cout...` 是调试输出，提交时应删掉。

### main：建树、找根、输出

```cpp
int main(){
    int n;cin>>n;
    for(int i=1;i<=n;i++){
        cin>>h[i];
    }
    for(int i=1;i<n;i++){
        int l,k;cin>>l>>k;
        bo[k].push_back(l);
        v[l]=1;
    }
    int st;
    for(int i=1;i<=n;i++){
            if(!v[i]) {st=i;break;}
        }
    dp(st);
    cout<<max(f[st][0],f[st][1]);
}
```

- 先读 $n$ 个点的权值，再读 $n-1$ 条父子关系；每条关系里 `l` 是下属、`k` 是上司，`bo[k].push_back(l)` 挂边，`v[l]=1` 标记 `l` 有上司。
- `int st;` 声明后**未初始化**，靠下面的循环把它赋成入度为 0 的根；合法输入恰好有一个根，所以一定能赋上值。
- 答案取 `max(f[st][0], f[st][1])`：根可以选也可以不选。

## 复杂度分析

- **时间复杂度**：$O(n)$。DFS 每个节点访问一次，每次合并儿子是 $O(1)$ 的累加，总计 $O(n)$。
- **空间复杂度**：$O(n)$。邻接表加上 `h`、`f`、`v` 三个数组，均为 $O(n)$。

## 适用场景

- 树上的最大权独立集（相邻节点不能同时被选），即本题「没有上司的舞会」。
- 一切「决策只在父子之间传递」的树形问题，如树上最小点覆盖、树上最大匹配（转移思路同源）。
- 更一般地，任何能把「子树」当作整体再向上合并的树形结构问题。

## 常见陷阱与注意事项

1. **必须后序递归**：先 `dp(y)` 再更新 `f[x]`，否则会用到儿子的初值。
2. **建边方向**：源程序只建「上司 → 下属」的单向边，因此递归不判父节点；若改成双向边，必须补 `if (y == fa) continue;`，否则会来回递归。
3. **根可能找不到**：`v[i]` 全为 1 时 `int st;` 不会被赋值，`dp(st)` 就成了未定义行为；本题保证是合法的树，可忽略。
4. **权值可能为负**：`f[x][0]=0`、`f[x][1]=h[x]` 的初始化默认了「不选一定不亏」，若权值有负数要重新审视初值。
5. **递归爆栈**：链状树深度可达 $n$，$n$ 很大时要留意栈空间。
6. **函数名与数组名易混**：源程序用 `dp` 当函数名、`f` 当数组名，`dp(st)` 是调用函数而不是访问数组，别被名字带偏。

## 对比与扩展

- 与「树形 01 背包」相比，本题只有「选 / 不选」两态，转移只需累加子节点值，不必枚举容量分配。
- 若把树退化成链，本题等价于「相邻不能同时选」的最大子段和类问题。
- 若图不是树而是一般图，最大独立集是 NP-hard；$O(n)$ 的树形 DP 完全依赖树的无环性。

