```

**解释：**

- 第一组、第一次修改后成本序列为 $\{5, 3, 7, 100, 4, 3, 12, 5, 100, 1\}$，最优是在 $2,4,6,9$ 处架塔。
- 第一组、第二次修改后成本序列为 $\{5, 10, 7, 100, 4, 15, 12, 5, 100, 1\}$，最优是在 $1,4,5,8,9$ 处架塔。
- 第二组无需架塔，答案为 $0$。
- 第三组必须在 $3$ 处架塔，答案就是 $a_3$。

## 解题思路

### 先去掉修改和必选：一个滑动窗口 DP

把 $0$ 和 $n+1$ 看成两个免费的、必选的「塔」（成本为 $0$）。问题变成：在 $0\sim n+1$ 里选一个子序列，包含 $0$ 和 $n+1$，相邻两项差不超过 $k$，最小化所选位置的成本和。

设 $f_i$ 表示「在 $i$ 建塔，且 $0\sim i$ 这一段已经合法」的最小成本。上一座塔 $j$ 必须在 $[i-k, i-1]$ 里：

$$f_i=a_i+\min_{j\in[i-k,\,i-1]} f_j,\qquad f_0=0$$

答案是 $f_{n+1}$（$a_{n+1}=0$）。

朴素的转移是 $O(nk)$ 的，但这是标准的**定长滑动窗口最小值**，用单调队列可以做到 $O(n)$。

### 加上必选：遇到必选就清空队列

如果 $i$ 是必选点，那么任何「$j\to i'$（$i'>i$）」的转移里，$j$ 都不可能小于 $i$——因为链必须经过 $i$，过不了 $i$ 的位置作废。

所以处理到必选点 $i$ 时：

1. 先用当前队列算出 $f_i$；
2. 然后把整个队列清空，只把 $i$ 放进去。

清空之后，后面的位置只能从 $i$ 往后选上一座塔，正好满足「必须经过 $i$」。

### 后缀 DP

由于「相邻差不超 $k$」这个约束左右对称，可以倒着再做一遍：

$$g_i=a_i+\min_{j\in[i+1,\,i+k]} g_j,\qquad g_{n+1}=0$$

$g_i$ 表示「在 $i$ 建塔，且 $i\sim n+1$ 这一段合法」的最小成本。必选点的处理方式完全对称：处理完 $g_i$ 后清空队列。

### 修改怎么处理

单点修改只影响 $k$ 邻域内的直接转移，但间接影响会一路传下去，所以不能只重算 $k$ 个 $f$。

关键在于：把答案拆成「左半边 + 右半边」。设被改的位置是 $x$，新值是 $v$。

**情况 A：$s_x=\texttt{1}$（必选）。**

$x$ 一定要建塔，$f_{n+1}$ 里已经包含了 $a_x$，所以答案就是

$$f_{n+1}-a_x+v$$

**情况 B：$x$ 不必选。** 分两种子情况：

1. **在 $x$ 建塔**：左边用 $f$、右边用 $g$，两边在 $x$ 处拼接、互不影响，代价为

$$v+\min_{i\in[\max(l,x-k),\,x-1]} f_i+\min_{j\in[x+1,\,\min(r,x+k)]} g_j$$

2. **不在 $x$ 建塔**：那就要跨过 $x$，即存在 $i<x<j$ 且 $j-i\le k$，代价为

$$\min_{i}\Big(f_i+\min_{j\in[x+1,\,\min(r,\,i+k)]} g_j\Big)$$

其中 $i$ 取 $[\max(l,x-k),\,x-1]$，且要满足 $i+k\ge x+1$。

这里的 $l$ 是 $x$ 左边最近的必选位置，$r$ 是右边最近的必选位置（$0$ 和 $n+1$ 也算必选）。

**为什么要卡 $l$ 和 $r$？** 因为 $f_i$ 只保证 $0\sim i$ 合法。如果 $i<l$，那么 $i\to x$ 这一段会跳过必选点 $l$，这个方案非法；同理 $j>r$ 会跳过 $r$。

### 情形 B2 的双指针

固定 $i$ 时，右侧要的是一段以 $x+1$ 开头、右端点随 $i$ 单调右移的区间的最小值。随着 $i$ 增大，$\min(r,i+k)$ 单调不减，所以可以用一个指针 `je` 一路向右扩展，用 `mg` 维护已经扫过部分的最小 $g$。

这样每次询问的总代价是 $O(k)$，加上预处理 $O(n)$，整体 $O(n+qk)$。

## 逐行代码解析

### 头文件与全局数组

```cpp
#include <bits/stdc++.h>
using namespace std;
#define int long long
#define PII pair<int,int>
#define fi first
#define se second
const int N=5e5+10,INF=1e18;
int a[N],dp[N],g[N],pre[N],nxt[N];
```

- `#define int long long`：$a_i$ 到 $10^9$、最多选 $5\times10^5$ 个点，总和能到 $10^{14}$，必须开 `long long`。
- `PII` 是单调队列里存的 `(下标, dp 值)`。
- `dp` 是前缀 DP，`g` 是后缀 DP；`pre[i]` / `nxt[i]` 分别是 $i$ 左右最近的必选位置。
- `INF=1e18` 作为「不可达」的哨兵。

### 前缀 DP：单调队列

```cpp
signed main(){
	ios::sync_with_stdio(0);
	cin.tie(0);cout.tie(0);
	int t;cin>>t;
	while(t--){
		int n,k,q;cin>>n>>k;
		a[0]=0;a[n+1]=0;
		for(int i=1;i<=n;i++){
			cin>>a[i];
		}
		string s;cin>>s;s='1'+s+'1';
		deque<PII> h;h.push_back({0,0});
		for(int i=1;i<=n+1;i++){
			while(h.size()&&h.front().fi<i-k) h.pop_front();
			dp[i]=h.front().se+a[i];
			if(s[i]=='1') while(h.size()) h.pop_back();
			else while(h.size()&&h.back().se>dp[i]) h.pop_back();
			h.push_back({i,dp[i]});
		}
```

- `a[0]=a[n+1]=0`：两个索道站免费且必建。
- `s='1'+s+'1'`：把下标平移到 $0\sim n+1$，同时把两头标成必选，后面统一处理。
- 队列里存 `(位置, dp 值)`，并保持 `dp` 值单调递增。
- `h.front().fi < i-k` 弹出过期的队头：第 $i$ 个位置只能从 $[i-k,i-1]$ 转移。
- 先算 `dp[i]`，再决定怎么入队：**必选点清空整个队列**（只留自己），**非必选点按单调性从队尾弹掉更差的**。
- 注意 $i=n+1$ 时也会走一遍循环，正好把 $f_{n+1}$ 算出来。

### 后缀 DP

```cpp
		while(h.size()) h.pop_back();
		g[n+1]=0;
		h.push_back({n+1,0});
		for(int i=n;i>=0;i--){
			while(h.size()&&h.front().fi>i+k) h.pop_front();
			g[i]=h.front().se+a[i];
			if(s[i]=='1') while(h.size()) h.pop_back();
			else while(h.size()&&h.back().se>g[i]) h.pop_back();
			h.push_back({i,g[i]});
		}
```

- 先清空队列复用，把 $n+1$ 作为后缀的起点（$g_{n+1}=0$）。
- 方向反过来，过期判断也反过来：`h.front().fi > i+k` 说明太远了。
- 必选处理与正向完全对称。
- 循环到 $i=0$ 结束，`g[0]` 就是「从 $0$ 一路走到 $n+1$」的代价，理论值等于 `dp[n+1]`。

### `pre` / `nxt` 预处理

```cpp
		pre[0]=0;
		for(int i=1;i<=n+1;i++){
			if(s[i]=='1') pre[i]=i;
			else pre[i]=pre[i-1];
		}
		nxt[n+1]=n+1;
		for(int i=n;i>=0;i--){
			if(s[i]=='1') nxt[i]=i;
			else nxt[i]=nxt[i+1];
		}
```

- `pre[i]`：$\le i$ 的最近必选位置；`nxt[i]`：$\ge i$ 的最近必选位置。
- 因为 $s_0$ 和 $s_{n+1}$ 都是 `'1'`，两个数组不会出现「找不到」的情况，省掉边界判断。

### 询问：必选点与「在 $x$ 建塔」

```cpp
		cin>>q;
		while(q--){
			int x,y;cin>>x>>y;
			if(s[x]=='1'){
				cout<<dp[n+1]-a[x]+y<<'\n';
				continue;
			}
			int ans=INF;
			int l=pre[x],r=nxt[x];
			int lmi=INF,rmi=INF;
			for(int i=max(l,x-k);i<=x-1;i++) lmi=min(lmi,dp[i]);
			for(int j=x+1;j<=min(r,x+k);j++) rmi=min(rmi,g[j]);
			if(lmi<INF&&rmi<INF) ans=min(ans,y+lmi+rmi);
```

- `s[x]=='1'`：必选点，直接替换成本即可，不用重跑 DP。
- `l=pre[x]`、`r=nxt[x]`：因为 $x$ 不是必选点，`pre[x]` 就是左边最近的必选点、`nxt[x]` 是右边最近的必选点。
- 左边窗口下界取 `max(l, x-k)`，右边窗口上界取 `min(r, x+k)`，两个方向互相独立。
- `lmi` / `rmi` 都是 $O(k)$ 暴力扫，因为 $k\le 3\times10^3$、$q\le 3\times10^3$，乘起来在可接受范围内。
- 三个量相加即为「在 $x$ 建塔」的答案。

### 询问：「不在 $x$ 建塔」

```cpp
			int mg=INF,je=x;
			for(int i=max(l,x-k);i<=x-1;i++){
				if(i+k<x+1) continue;
				int lim=min(r,i+k);
				while(je<lim){
					je++;
					mg=min(mg,g[je]);
				}
				if(mg<INF) ans=min(ans,dp[i]+mg);
			}
			cout<<ans<<'\n';
		}
	}
	return 0;
}
```

- `i+k<x+1` 说明左边这座塔够不到 $x$ 右边，跳过。
- `lim=min(r,i+k)`：右端点是「够得最远」和「不越过下一个必选点」的较小值。
- `je` 只向右移动，`mg` 维护 $[x+1,\text{je}]$ 上 $g$ 的最小值；由于 `lim` 单调不减，`mg` 无需回退。
- 最后 `ans` 取两种子情况的最小值输出。

## 复杂度分析

预处理 `dp`、`g`、`pre`、`nxt` 都是 $O(n)$；每次询问两段暴力扫 $O(k)$ 加一次双指针 $O(k)$，共 $O(k)$。单组总复杂度 $O(n+qk)$，空间 $O(n)$。$\sum n\le2\times10^6$、$\sum k\le10^4$、$\sum q\le10^4$ 的约束正好对应这个复杂度。

## 常见陷阱与注意事项

- **必选点要清空队列**，不是简单跳过；只清空会漏掉「链必须经过 $i$」的约束。
- **两头要标成必选**：`s='1'+s+'1'`，否则 `pre/nxt` 会越界或找不到。
- **询问时窗口要卡 $l,r$**：不卡的话会生成跳过必选点的非法方案，答案偏小。
- **`i+k<x+1` 必须跳过**：否则 $j$ 区间为空，`mg` 保持 `INF` 或残留旧值。
- **`mg` 不能回退**：`je` 只增不减，`mg` 也只对扩展部分取 min，这与双指针的正确性绑定。
- **必选点修改**用 `dp[n+1]-a[x]+y`，注意 `dp[n+1]` 里只算了一次 $a_x$。

## 对比与扩展

- 与「P7114 字符串匹配」的关系：那道题用调和级数把枚举量压到 $O(n\log n)$，本题用单调队列把 DP 压到 $O(n)$，都是「找到被重复计算的部分并一次性维护」。
- 拓展提到的 $(min,+)$ 半环矩阵做法：把「最近 $k$ 个 $f$ 的转移」写成 $k\times k$ 矩阵，用矩阵快速幂处理「查询任意区间」的场景。本题单点修改用前后缀 DP 更简单，但那个思想在 $k$ 很小、查询区间任意时非常关键。
- 「必选点分段」也是一种合法写法：把序列按必选点切成若干段分别做 DP，但代码里用清空队列更短。$AKB459$, '动态规划', array['单调队列', '动态规划', '前后缀DP', '单点修改', '滑动窗口'], null, '提高', 'problem'),
('Xesir', 'col-prob-luogu-p1450--xesir', 'P1450 [HAOI2008] 硬币购物 · Xesir', $AKB460$## 题目描述

共有 $4$ 种硬币，面值分别为 $c_1,c_2,c_3,c_4$。

某人去商店买东西，去了 $n$ 次。对于每次购买，他带了 $d_i$ 枚第 $i$ 种硬币，想购买 $s$ 的价值的东西。请问每次有多少种付款方法。

### 输入格式

输入的第一行是五个整数，分别代表 $c_1,c_2,c_3,c_4, n$。

接下来 $n$ 行，每行有五个整数，描述一次购买，分别代表 $d_1, d_2, d_3, d_4, s$。

### 输出格式

对于每次购买，输出一行一个整数代表答案。

### 数据范围

对于 $100\%$ 的数据，保证 $1 \le c_i, d_i, s \le 10^5$，$1 \le n \le 1000$。

## 样例

### 样例 1

**输入：**

```
1 2 5 10 2
3 2 3 1 10
1000 2 2 2 900
```

**输出：**

```
4
27
```

## 解题思路

题面要求的是计算满足

$$\sum_{i=1}^{4} c_i x_i = s,\qquad x_i \le d_i$$

的方案数。

「每种硬币有上限」这个约束不好直接做，考虑**补集**：先算不带上限的方案数，再减去「至少有一种硬币超限」的方案数。

用容斥原理：枚举一个集合 $S$ 表示「$S$ 里的硬币都超出上限」，其余硬币不做约束。偶加奇减就得到合法方案数。

怎么算「至少 $S$ 超限」的方案数？假设 $S$ 里的硬币都超出约束，那么对每个 $i\in S$ 有

$$x_i = d_i + 1 + cur_i,\qquad cur_i \ge 0$$

把多出来的 $c_i(d_i+1)$ 先从总价值里扣掉，剩下的部分对四种硬币都**没有上限**——相当于跑一次完全背包，取 $s-\sum_{i\in S}c_i(d_i+1)$ 处的 $dp$ 值即可。

由于 $c_i$ 固定，完全背包可以只预处理一次。总复杂度 $O(16n+s)$。

### 为什么想到补集

直接做的话，每种硬币都有一个上限 $d_i$，四维枚举显然不现实。而「上限」这类约束有一个特点：**去掉它之后问题极简单**（就是无限背包），加上它才变难。

所以走补集：先不管上限，算出「凑出 $s$ 的全部方案」，再减掉「某个硬币超额」的那些方案。

### 容斥的完整写法

设 $A_i$ 表示「第 $i$ 种硬币使用数量超过 $d_i$」的方案集合，我们要的是 $\left|\overline{A_1}\cap\overline{A_2}\cap\overline{A_3}\cap\overline{A_4}\right|$。由容斥：

$$\text{ans}=\sum_{S\subseteq\{1,2,3,4\}}(-1)^{|S|}\left|\bigcap_{i\in S}A_i\right|$$

其中 $S=\varnothing$ 那一项就是「完全无上限」的方案数。集合 $S$ 只有 $2^4=16$ 种，逐个枚举即可。

### 为什么扣掉 $c_i(d_i+1)$ 就变回无上限

固定一个 $S$，要求每个 $i\in S$ 都超额。注意「超额」只是一个下界：只要用了 $d_i+1$ 枚就一定超了，多出来的部分可以是任意多枚。所以令

$$x_i=(d_i+1)+y_i,\qquad y_i\ge 0$$

对每个 $i\in S$ 都这样替换，代回 $\sum c_ix_i=s$：

$$\sum_{i\in S}c_i(d_i+1)+\sum_{i\in S}c_iy_i+\sum_{j\notin S}c_jx_j=s$$

移项后，左边剩下的部分就是「四种硬币都无上限」的方程。于是只要先扣掉 $\sum_{i\in S}c_i(d_i+1)$，剩下价值 $s'$ 的方案数正好是预处理的完全背包值 $f[s']$。$s'<0$ 说明无解，贡献 $0$。

### 手算样例

第一组：$c=(1,2,5,10)$，$d=(3,2,3,1)$，$s=10$。

先看有哪些合法方案：

| 方案 | 是否合法 |
|---|---|
| $10\times1$（即 $10$ 枚 $1$ 元） | ✗ 超过 $d_1=3$ |
| $1+2+2+5=10$，即 $x=(1,2,1,0)$ | ✓ |
| $3+2+5=10$，即 $x=(3,1,1,0)$ | ✓ |
| $5+5=10$，即 $x=(0,0,2,0)$ | ✓ |
| $10=10$，即 $x=(0,0,0,1)$ | ✓ |

共 $4$ 种，与样例输出一致。容斥的做法会先算出全部无上限方案，再依次减掉「$1$ 元超 3 枚」「$2$ 元超 2 枚」……最后剩下的正好是上面这 $4$ 种。

## 逐行代码解析

### 头文件与全局数组

```cpp
#include <bits/stdc++.h>
using namespace std;
#define int long long
const int N=1e5+10;
int f[N],c[4],d[4];
```

- `#define int long long`：答案规模可能超过 `int`，统一开 `long long`，同时 `main` 要写成 `signed main`。
- `f[j]` 是完全背包的 DP 数组，`c[4]`、`d[4]` 分别存面值与每次购买的数量上限。
- `N=1e5+10` 对应 $s$ 的上界。

### 预处理完全背包

```cpp
signed main(){
    ios::sync_with_stdio(0);
    cin.tie(0);cout.tie(0);
    for(int i=0;i<4;i++) cin>>c[i];
    int n;cin>>n;
    f[0]=1;
    for(int i=0;i<4;i++){
        for(int j=0;j<N;j++){
            if(j-c[i]>=0) f[j]+=f[j-c[i]];
        }
    }
```

- `f[0]=1` 是方案数的初值：凑出 $0$ 元有 $1$ 种（什么都不选）。
- 外层枚举硬币种类、内层**正序**枚举价值，这正是完全背包的写法——每种硬币可以用无限次。
- `if(j-c[i]>=0)` 防止越界，也可以把循环起点改成 `j=c[i]`。
- 这一步只与面值有关，与询问无关，所以放在读入询问之前做一次。

### 逐次询问 + 容斥

```cpp
    while(n--){
        for(int i=0;i<4;i++) cin>>d[i];
        int s;cin>>s;
        int ans=0;
        for(int i=0;i<16;i++){
            int cnt=s,res=0;
            for(int j=0;j<4;j++){
                if(i&(1<<j)) cnt-=(d[j]+1)*c[j];
            }
            if(cnt>=0) res=f[cnt];
            if(__builtin_popcountll(i)&1) ans-=res;
            else ans+=res;
        }
        cout<<ans<<'\n';
    }
    return 0;
}
```

- `for(int i=0;i<16;i++)` 枚举 $2^4=16$ 个集合，第 $j$ 位为 $1$ 表示「第 $j$ 种硬币超限」。
- `cnt-=(d[j]+1)*c[j]`：把超限的那部分先扣掉，剩下的价值交给无上限背包。
- `if(cnt>=0) res=f[cnt];`：扣成负数说明这种组合不可能，贡献为 $0$。
- `__builtin_popcountll(i)&1` 判断集合大小的奇偶：奇数个超限就减，偶数个就加——这就是容斥的「偶加奇减」。
- 内层 `for` 结束后直接输出 `ans`，多组询问互不影响。

## 复杂度分析

完全背包预处理是 $O(4N)$；每次询问枚举 $16$ 个集合、每个集合扫 $4$ 种硬币，是常数 $64$，所以 $n$ 次询问总共 $O(16n)$。合计 $O(16n+s)$ 量级，空间 $O(s)$。

## 常见陷阱与注意事项

- **超限要减 `d[j]+1` 而不是 `d[j]`**：超出上限至少要买 $d_j+1$ 枚，写成 $d_j$ 会把「刚好用满」的情况错误地算进补集。
- **扣成负数要判掉**：`cnt<0` 时 $f[cnt]$ 是越界访问，必须先判 `cnt>=0`。
- **多组询问别重建背包**：`f` 只与面值有关，重建会多出 $n$ 倍的常数。
- **容斥符号**：奇数次超限减、偶数次加，写反会得到负数或者答案翻倍。
- **`#define int long long` 与 `main`**：必须写 `signed main`，否则编译报错。
- **数组上界**：$s\le10^5$，`N` 开小了会越界读。

## 对比与扩展

- 与「P3758 可乐」的关系：那道题用矩阵把时间维压掉，本题用容斥把「上限」这个约束压掉，都是「换一种表示让问题变简单」。
- 如果硬币种类从 $4$ 增加到 $k$，容斥部分会退化成 $O(2^k n)$，$k$ 一大就不能这么做了。
- 这类「带上限的完全背包计数」是容斥的经典模型，和「隔板法 + 上限」是同一类思路。$AKB460$, '动态规划', array['容斥原理', '完全背包', '计数'], null, '提高+/省选−', 'problem'),
