$n$ 堆石子排成一个环，每次可以合并相邻的两堆，得到的新堆石子数就是这一次合并的得分，合并后堆数减一，直到只剩一堆。要求的是一串合并方案下总得分的**最小值**与**最大值**。

用区间记号写：$s(i,j)$ 表示第 $i$ 堆到第 $j$ 堆的石子总数（也就是这一段合并完的代价），转移就把区间分成左右两段。

