本文只给思路，代码留空，后续填写。正文中的代码块与 `codePath` 指向的 `.cpp` 文件保持一致，目前只有一行头文件：

```cpp
#include <iostream>
```

- `check` 里用到的 $f_x$、$f_y$ 都是已经算好的值，注意 $x$ 是旧决策点、$y$ 是新决策点，两边不要写反。
- 计算绝对值幂时用 long double；若手写快速幂，底数也要是 long double 类型，别在 int 上取幂。
- 二分的区间取 $[\max(i+1,l),\,r]$，同时要判掉区间为空的情况。
- 队列初始化时把决策点 $0$ 的区间设为 $[1,n]$，这样状态 $1$ 就一定有决策点可用。
- 拆队头区间时先改队头的右端点，再插入新元素，保证队列仍按决策点下标递增。

## 复杂度分析

- 时间：$O(n\log n\log P)$。每个决策点只会入队一次、出队一次，所以弹队的总次数是 $O(n)$，这部分是势能分析下的均摊 $O(n)$；每次插入新决策点要做一次二分，二分 $O(\log n)$ 次判定，每次判定内部还要算一次绝对值的 $P$ 次幂，快速幂是 $O(\log P)$，于是总的是 $O(n\log n\log P)$。
- 空间：$O(n)$。需要存 $f$ 数组和单词长度的前缀和 $s$，单调队列的元素个数不超过 $n$。

## 常见陷阱与注意事项

1. **二分范围写成 $[l,r]$ 会错**：下界必须是 $\max(i+1,l)$。新决策点 $y=i$ 对 $mid\le i$ 的状态是非法的，直接拿它去比会算出错误的分界点。
2. **精度**：数据范围大，必须用 long double 存 DP 值，否则比较 $f_x+w$ 与 $f_y+w$ 时会因为精度误差判错分界位置。
3. **$p$ 落在区间外要分开处理**：$p\le l$ 是整段被压住（继续弹），$p>n$ 是整段都没优势（跳过）。这两种情况处理方式完全不同，混在一起写就会多弹或少弹。
4. **弹过期和弹劣势不是一回事**：前者看区间右端点是否小于 $i$，后者靠二分比较代价，两个循环别合并成一个条件。
5. **队列为空**：如果一路弹到队列为空，说明新决策点覆盖了从 $i+1$ 到 $n$ 的全部区间，此时直接入队即可，不要再取队头。
6. **初始状态**：别忘了把 $j=0$（也就是一行都还没排）作为第一个决策点放进队列，否则第一个状态无法转移。

## 对比与扩展

把这道题和同组的另外三道放在一起看，能看出一条很清晰的路线：

| 题目 | 优化手段 | 决策点结构 |
|---|---|---|
| P1912 诗人小G | 决策单调性 + 单调队列维护决策区间 | 每个决策点占一段连续状态 |
| P1880 石子合并 | 区间 DP + Knuth 定理双向夹逼 | $\text{opt}(i,j)$ 夹在 $\text{opt}(i,j-1)$ 与 $\text{opt}(i+1,j)$ 之间 |
| P4767 邮局 | 分层 DP + Knuth 定理 | 同样双向夹逼，但外层枚举段数 |
| P5574 任务分配问题 | 分层 DP + 分治优化 | 分治时把决策点候选区间一起往下传 |

单调队列这一套适合「一层线性 DP、决策点只向右移动、需要在线按顺序求值」的场合；Knuth 是四边形不等式在区间 DP 上的特例，给出的是双向夹逼而不是单向移动；分治优化则适合分层 DP，同一层的状态互不依赖，可以离线整体求解。再往后走，当转移能写成直线形式时就轮到斜率优化与李超线段树，而四边形不等式失效时还可以考虑 CDQ 分治去除偏序限制。$AKB462$, '动态规划', array['动态规划', '决策单调性', '四边形不等式', '单调队列'], null, '省选/NOI−', 'problem'),
