## 题目描述

原文未附题面，以下题意根据作者思路整理。

有 $n$ 个位置排成一列，第 $i$ 个位置上的数是 $a_i$。每次操作可以把某个位置上的数改成 $j$，代价是 $|j-a_i|$，并且要求改完之后整个序列单调不降。求最小总代价。

原文给出的状态是：$f_{i,j}$ 表示「操作到第 $i$ 个数字、并把这个数字变成 $j$」的最小代价，转移为

$$f_{i,j}=\min_{k\le j}f_{i-1,k}+|j-a_i|$$

其中 $k\le j$ 这个条件对应「最终序列单调不降」。

原文只给了这个状态与转移式，题目本身的背景、操作规则细节都没有写。

