$$a(s_i-s_j)^2+b(s_i-s_j)+c$$

原文只说明 $f_i$ 表示「划分到第 $i$ 位可以划分出来的最大战斗力」，没有进一步交代 $a,b,c$ 的含义与取值范围（后面的推导只用到 $a<0$ 这一条）。转移为

$$f_i=\max_{j<i}\left(f_j+a(s_i-s_j)^2+b(s_i-s_j)+c\right)$$

