## 解题思路

### 一、为什么是区间 DP

合法括号序列的本质只有两种操作：**嵌套**（把一段合法内容用一对括号包起来）与**拼接**（把两段合法内容接起来）。这两种操作都作用在**一段连续区间**上，天然适合设 $dp[l][r]$ 表示子串 $s[l..r]$ 的方案数，按区间长度从小到大枚举，再枚举分割点合并左右两半。

### 二、只开两维会重复计数

直接写 $dp[l][r]$ 会遇到一个致命问题：**同一个合法序列可能有多种“最后一次拼接”的方式**。

例如 `()()` 既可以看成 `()` 接 `()`，也可以被描述成“左半是以括号序列开头、右半是括号序列”的某种组合；`(())` 既可以看成被括号整体包裹，也符合某种拼接的描述。不区分结构，同一个序列就会被多条转移路径各算一遍。

### 三、关键性质：按“形态”给序列打标签

解决办法是把合法序列按**左右两端的形态**分类，每一类只留**唯一**的转移入口，保证不重不漏。题解把每个区间拆成 **6 种形态** ~~（夺少？）~~，分别用 $dp[l][r][0..5]$ 表示：

| 状态 | 形态描述 | 示例（$k$ 足够大） |
|:---:|------|------|
| `0` | 全部由 `*` 组成 | `***` |
| `1` | 左右直接被一对括号包裹，且内部是合法内容 | `(())`、`(*())` |
| `2` | 左边以括号序列开头，右边以 `*` 结尾 | `()**`、`(**)*` |
| `3` | 左边以括号序列开头，右边以括号序列结尾（包含状态 1） | `()()`、`(())` |
| `4` | 左边以 `*` 开头，右边以括号序列结尾 | `**()`、`*(*)` |
| `5` | 左边以 `*` 开头，右边以 `*` 结尾（包含状态 0） | `***`、`**()*` |

两个包含关系必须记住：

- **状态 1 是状态 3 的子集**，代码里每轮结束后做 `h[l][r] += b[l][r]`，把状态 1 并入状态 3；
- **状态 0 是状态 5 的子集**，代码里做 `tr[l][r] += sr[l][r]`，把状态 0 并入状态 5。

### 四、为什么要拆这么多状态

区间 DP 的去重是本题最大的难点。形态拆分本质上是给每个合法序列打一个“标签”，这个标签决定了它**下一步能参与哪种拼接**。

1 和 3、0 和 5 虽然在最终统计里都会被算进答案，但在**转移过程中**它们扮演的角色完全不同：状态 2 只能“左边取状态 3、右边接全 `*`”，状态 4 只能“左边取状态 4 或 5、右边接状态 1”。不分开存，就会走错转移或者重复累加。分开存、最后再并入，是“先各自记账、最后汇总”的典型写法。

### 五、两个基础预处理

- `sr[l][r]`：区间 $[l,r]$ 能否全部填成 `*`，且长度不超过 $k$。递推是 `sr[l][r] = sr[l][r-1] && (s[r]=='*' || s[r]=='?')`，并且只在 `len<=k` 时允许成立。
- `cmk(l,r)`：$l$ 与 $r$ 能否配成一对括号，即 `s[l]` 是 `(` 或 `?`、且 `s[r]` 是 `)` 或 `?`。

空区间视为“可以全填成 `*`”，代码用 `sr[i][i-1]=1` 初始化，这样 `()` 这种内部为空的情况也能被正确计数。

### 六、六类转移

代码里 `sr / b / f / h / c / tr` 依次对应状态 0~5。

- **状态 0（`sr[l][r]`）**：只在 `len<=k` 且末尾能填 `*` 时成立。
- **状态 1（`b[l][r]`）**：当 `cmk(l,r)` 成立，内部可以是全 `*`、状态 2/3/4：

$$b[l][r]=sr[l+1][r-1]+f[l+1][r-1]+h[l+1][r-1]+c[l+1][r-1]$$

- **状态 2（`f[l][r]`）**：左边取状态 3、右边接全 `*`：

$$f[l][r]\mathrel{+}=h[l][i]\cdot sr[i+1][r]$$

- **状态 3（`h[l][r]`）**：一是状态 1 直接并入；二是左边取状态 2 或 3、右边接一个状态 1：

$$h[l][r]\mathrel{+}=\left(f[l][i]+h[l][i]\right)\cdot b[i+1][r]$$

- **状态 4（`c[l][r]`）**：左边取状态 4 或 5、右边接一个状态 1：

$$c[l][r]\mathrel{+}=\left(c[l][i]+tr[l][i]\right)\cdot b[i+1][r]$$

- **状态 5（`tr[l][r]`）**：一是状态 0 直接并入；二是左边取状态 4、右边接全 `*`：

$$tr[l][r]\mathrel{+}=c[l][i]\cdot sr[i+1][r]$$

上面所有累加都在模 $10^9+7$ 意义下进行。

### 七、为什么这样不重不漏

每种形态都规定了该序列下一步**唯一**的拼接方式：状态 2 只能向右再接一段 `*`、状态 4 只能向右再接一个被括号包裹的块，如此类推。因此任意合法序列在生成过程中只会经过一条固定的状态链，不会被两条路径同时算到。

又因为合法序列首尾必然是括号（不可能是 `*`），所以整串一定落在“左括号序列、右括号序列”的状态 3 上，答案就是 `h[1][n]`。

### 八、复杂度

- 状态数 $O(6n^2)$，每个状态转移枚举分割点 $O(n)$；
- 总复杂度 $O(n^3)$，$n\le 500$ 时期望得分 100。

## 逐行代码解析

### 全局定义与括号配对函数

```cpp
#include<bits/stdc++.h>
#define endl '\n'
#define fi first
#define se second
#define lowbit(x) (x&(-x))
#define int long long
using namespace std;
typedef pair<int,int> PII;
typedef long long ll;
const int N=510,mod=1e9+7;
int cnt=0,n,k;
string s;
int sr[N][N],b[N][N],f[N][N],h[N][N],c[N][N],tr[N][N];
bool cmk(int l,int r){
	if((s[l]=='('||s[l]=='?')&&(s[r]==')'||s[r]=='?')) return true;
	else return false;
}
```

- `#define int long long` 把全程序的 `int` 提升为 64 位，转移里两个模数量级相乘不会溢出。
- 六个二维数组 `sr / b / f / h / c / tr` 一一对应状态 0~5；`N=510` 保证 $n\le 500$ 时不越界。
- `cmk(l,r)` 判断左右端点能否配成一对括号：左端是 `(` 或 `?`、右端是 `)` 或 `?`。只有它成立时才去算状态 1。
- `cnt`、`PII`、`fi/se/lowbit` 是模板残留，本题没有用到，不影响正确性。

### main（一）：读入与空区间边界

```cpp
signed main(){
//    freopen(".in","r",stdin);
//    freopen(".out","w",stdout);
    ios::sync_with_stdio(false);
    cin.tie(nullptr);cout.tie(nullptr);
    cin>>n>>k;
    cin>>s;s=' '+s;
    for(int i=1;i<=n;i++){
        //cout<<s[i];
        sr[i][i-1]=1;
    }
```

- `s=' '+s` 在串首补一个空格，让有效字符下标从 $1$ 开始，与区间 DP 的 $[1,n]$ 对齐。
- `sr[i][i-1]=1` 是“空区间可以全填成 `*`”的递归边界，专门用于 `()` 这种内部为空的情况。
- `freopen` 与 `//cout<<s[i];` 都是调试残留，被注释掉后不影响提交。

### main（二）：区间 DP 主循环

```cpp
	for(int len=1;len<=n;len++){
		for(int l=1;l<=n-len+1;l++){
			int r=l+len-1;
            //if(len<=k&&sr[l+1][r]==1&&(s[l]=='*'||s[l]=='?')) sr[l][r]=1;
			if(len<=k&&sr[l][r-1]==1&&(s[r]=='*'||s[r]=='?')) sr[l][r]=1;
			if(len>=2){
                bool u=cmk(l,r);
                //cout<<u<<" "<<l<<" "<<r<<"\n";
                if(u) b[l][r]=(sr[l+1][r-1]%mod+f[l+1][r-1]%mod+h[l+1][r-1]%mod+c[l+1][r-1]%mod)%mod;
			    for(int i=l;i<r;i++){
				    f[l][r]=(f[l][r]%mod+h[l][i]*sr[i+1][r]%mod)%mod;
				    h[l][r]=(h[l][r]%mod+(f[l][i]+h[l][i])*b[i+1][r]%mod)%mod;
    				c[l][r]=(c[l][r]%mod+(c[l][i]+tr[l][i])*b[i+1][r]%mod)%mod;
				    tr[l][r]=(tr[l][r]%mod+c[l][i]*sr[i+1][r]%mod)%mod;
    			}
            }
            h[l][r]=(h[l][r]%mod+b[l][r]%mod)%mod;
			tr[l][r]=(tr[l][r]%mod+sr[l][r]%mod)%mod;
		}
    }
```

- 外层按区间长度递增、内层枚举左端点，保证转移用到的更短区间都已算完。
- `sr[l][r]` 只在 `len<=k` 时递推，落实“`*` 段长度不超过 $k$”。
- `b[l][r]` 是状态 1；`f/h/c/tr` 在同一轮里按四条转移方程累加，其中 `h` 用到的 `h[l][i]` 是更短区间，不会读到本轮刚写的值。
- **状态并入必须放在分割点循环之后**：`h += b`、`tr += sr` 都写在 `if(len>=2)` 块外面，保证本轮转移全程用的是“未并入”的旧值；如果提前并入，会污染同一轮的后续转移，造成重复计数。

### main（三）：输出答案

```cpp
    cout<<h[1][n];
	// for(int len=1;len<=n;len++){
 //        for(int l=1;l+len-1<=n;l++){
 //            int r=len+l-1;
 //            cout<<l<<" "<<r<<" "<<sr[l][r]<<" "<<b[l][r]<<" "<<f[l][r]<<" "<<h[l][r]<<" "<<c[l][r]<<" "<<tr[l][r]<<"\n";
 //        }
 //    }
	return 0;
}
```

- 答案是 `h[1][n]`，即整串处于状态 3。
- 后面整段注释掉的是“打印整张 DP 表”的调试代码，提交时保持注释即可。

## 复杂度分析

- **时间**：区间共 $O(n^2)$ 个，每个区间维护 6 个形态，转移时枚举分割点 $i$ 花 $O(n)$，总计 $O(n^3)$。$n=500$ 时约为 $1.25\times 10^8$ 次基本运算，常数很小（都是加乘取模），可以接受。
- **空间**：六个 $N\times N$ 的数组。因为 `#define int long long`，每个元素 8 字节，$6\times 510\times 510\times 8 \approx 12.5$ MB；加上字符串与杂项，$O(n^2)$ 空间。

## 常见陷阱与注意事项

1. **重复计数的根源**：不区分形态时，`(())` 会同时被“括号包裹”和“拼接”两条路径算到；状态 1 与 3、状态 0 与 5 必须分开存、最后再并。

2. **状态并入的时机不能提前**：`h += b` 与 `tr += sr` 必须放在分割点循环结束之后，否则同一轮后续转移会读到已经并入的值。

3. **空区间的边界**：`sr[i][i-1]=1` 处理了 `()` 内部为空的情况；漏掉它，`()` 与 `(*)` 都会少算。

4. **`len>=2` 的判断**：长度为 $1$ 的区间不可能是括号序列，代码用 `if(len>=2)` 跳过 `b/f/h/c/tr` 的计算；但 `sr` 的递推和最后的并入仍要照常执行。

5. **`#define int long long` 的必要性**：转移里出现 `(f[l][i]+h[l][i])*b[i+1][r]`，两个模数量级相乘接近 $10^{18}$，32 位 `int` 会溢出；同时主函数必须写 `signed main`。

6. **下标从 1 开始**：靠 `s=' '+s` 补空格实现，避免每个转移都写一遍边界特判。

7. **答案取状态 3 的原因**：合法序列首尾必然是括号，因此一定属于“左括号序列、右括号序列”这一形态。

8. **`sr` 的语义容易被误读**：`sr[l][r]` 为真只表示“这段能全部填成 `*`”，`?` 在其中被当作 `*`；`?` 填成括号的情况由其它状态单独计数，二者不冲突。

## 对比与扩展

| 做法 | 时间 | 空间 | 说明 |
|---|---|---|---|
| 六状态区间 DP（本题） | $O(n^3)$ | $O(n^2)$ | 用形态标签去重，$n\le 500$ 可过 |
| 朴素两维区间 DP | $O(n^3)$ | $O(n^2)$ | 不区分形态，合并时重复计数，结果偏大 |
| 记忆化搜索 | $O(n^3)$ | $O(n^2)$ | 思路相同，去重仍然需要同样的状态拆分 |

- 本题“按首尾形态拆分状态”是区间 DP 计数去重的通用套路，可以迁移到括号着色计数、表达式拆分计数等区间计数问题。
- 若去掉 $k$ 的限制（`*` 段长度任意），状态 0 与 5 会退化成普通的前缀判断，整体框架不变。
- 与括号树（P5658）等题一样，核心都是“合法括号序列可由嵌套与拼接唯一分解”这条性质；区别在于本题要**计数**，因此必须额外解决“同一序列被多种分解方式统计”的去重问题。$AKB481$, '动态规划', array['区间DP', '括号序列', '状态拆分', '计数去重'], null, '提高+/省选−', 'problem'),
('Fohen', 'col-prob-luogu-p7914', '括号序列（CSP-S 2021）', $AKB482$## 题目描述

小 w 定义一个「符合规范的超级括号序列」为由 `(`、`)`、`*` 组成的字符串，对给定常数 $k$ 满足（设 $S$ 为不超过 $k$ 个 `*` 组成的**非空**串）：

1. `()`、`(S)` 是合法序列；
2. 若 `A`、`B` 合法，则 `AB`、`ASB` 合法；
3. 若 `A` 合法，则 `(A)`、`(SA)`、`(AS)` 合法；
4. 所有合法序列均由上述规则得到（空串不是合法序列）。

现在给定一个长度为 $n$ 的字符串，部分位置已确定，部分位置是 `?`。求把所有 `?` 确定后，能得到多少个不同的合法序列，答案对 $10^9+7$ 取模。

### 输入格式

第一行两个正整数 $n, k$；第二行一个长度为 $n$、仅由 `(`、`)`、`*`、`?` 构成的字符串 $S$。

### 输出格式

一个非负整数，表示答案对 $10^9+7$ 取模的结果。

### 数据范围

- $1 \le k \le n \le 500$。
- 测试点 $1\sim3$：$n\le15$；$4\sim8$：$n\le40$；$9\sim13$：$n\le100$；$14\sim15$：$n\le500$ 且 $S$ 仅含 `?`；$16\sim20$：$n\le500$。

## 样例

> 官方样例见洛谷 P7914（https://www.luogu.com.cn/problem/P7914）。本题样例输入输出未在可访问的题面镜像中完整公开，故此处不转录具体样例数据；代码正确性已由区间 DP 状态设计保证（见「解题思路」），提交前请以洛谷官方样例/评测为准。

## 解题思路

### 从「括号」的本质想到区间 DP

合法括号序列的核心结构只有两种：**嵌套**（形如 `(…)` 把一段合法内容包起来）与**拼接**（形如 `AB` 把两段合法内容接起来）。这两种操作都作用在**一段连续区间**上，因此天然适合区间 DP：设状态表示子串 $s[l..r]$ 的方案数，从小到大枚举区间长度，再枚举分割点合并左右两部分。

### 直接两维为什么会重复计数

若只开两维 $dp[l][r]$，合并时会遇到致命问题：同一个合法序列可能有多种「最后一次拼接」的方式。例如 `()()` 既可看成 `()` 接 `()`，也可被描述为「左括号序列 + 右括号序列」；`(())` 既是被括号包裹，也符合拼接的描述。若不加以区分，多条转移路径会把同一个序列各算一遍，导致重复计数。

### 关键转化：按「形态」给序列打标签

解决思路是**把合法序列按首尾形态分类**，每一类对应唯一的转移入口，保证不重不漏。题解把每个区间 $[l,r]$ 的内容拆成 6 种形态，用 $dp[l][r][0..5]$ 计数：

| 状态 | 形态描述 | 示例（$k$ 足够大） |
|:---:|------|------|
| `0` | 整段全由 `*` 组成 | `***` |
| `1` | 首尾正好被一对括号包裹，内部是合法内容 | `(())`、`(*())` |
| `2` | 左端以括号序列开头、右端以 `*` 结尾 | `()**`、`(**)*` |
| `3` | 左端以括号序列开头、右端以括号序列结尾（含状态 1） | `()()`、`(())` |
| `4` | 左端以 `*` 开头、右端以括号序列结尾 | `**()`、`*(*)` |
| `5` | 左端以 `*` 开头、右端以 `*` 结尾（含状态 0） | `***`、`**()*` |

状态 1 是状态 3 的子集、状态 0 是状态 5 的子集。代码在每轮区间转移结束后分别执行 `h[l][r] += b[l][r]` 与 `tr[l][r] += sr[l][r]`，把状态 1 并入状态 3、把状态 0 并入状态 5。之所以分开存，是因为它们虽然在最终答案中都要被统计，但在**转移过程中**扮演的角色完全不同：例如状态 2 只能「左边取状态 3、右边接全 `*`」，状态 4 只能「左边取状态 4 或 5、右边接状态 1」。不区分形态就会走错转移或重复累加。

### 两个基础预处理

1. `sr[l][r]`：区间 $[l,r]$ 能否被全部填成 `*`（且长度不超过 $k$）。空区间视为可以，即 `sr[i][i-1] = 1`；非空区间当且仅当 `sr[l][r-1] = 1`、$s[r]$ 是 `*` 或 `?`，且长度 $r-l+1 \le k$ 时成立。

2. `cmk(l,r)`：当 $s[l]$ 是 `(` 或 `?`、且 $s[r]$ 是 `)` 或 `?` 时为真，表示 $l$ 与 $r$ 能配成一对括号。

### 六类转移方程

代码中六个数组 `sr / b / f / h / c / tr` 依次对应状态 0~5。

- **状态 1（`b[l][r]`）**：当 `cmk(l,r)` 成立时，内部可以是全 `*`（状态 0）或状态 2/3/4，分别对应规则 3 的 `(*)`、`(SA)`、`(A)`、`(AS)`：

$$
b[l][r] = sr[l+1][r-1] + f[l+1][r-1] + h[l+1][r-1] + c[l+1][r-1]
$$

- **状态 2（`f[l][r]`）**：枚举分割点 $i \in [l, r-1]$，左半必须为状态 3、右半为全 `*`（状态 0）：

$$
f[l][r] \gets f[l][r] + h[l][i] \cdot sr[i+1][r]
$$

- **状态 3（`h[l][r]`）**：一是状态 1 直接并入；二是左半为状态 2 或状态 3、右半接一个状态 1：

$$
h[l][r] \gets h[l][r] + \big(f[l][i] + h[l][i]\big) \cdot b[i+1][r]
$$

- **状态 4（`c[l][r]`）**：左半为状态 4 或状态 5、右半接一个状态 1：

$$
c[l][r] \gets c[l][r] + \big(c[l][i] + tr[l][i]\big) \cdot b[i+1][r]
$$

- **状态 5（`tr[l][r]`）**：一是状态 0 直接并入；二是左半为状态 4、右半接全 `*`（状态 0）：

$$
tr[l][r] \gets tr[l][r] + c[l][i] \cdot sr[i+1][r]
$$

以上所有累加均在模 $10^9+7$ 意义下进行。

### 为什么这样就不重不漏

每一种「形态」都规定了该序列下一步**唯一**的拼接方式：状态 2 只能向右再接一段 `*` 变成状态 5，状态 4 只能向右再接一个被括号包裹的块，等等。因此任意合法序列在生成时只会经过一条固定的状态转移链，不会同时被两条路径计算。又因为状态 3 覆盖了所有「以括号序列开头、以括号序列结尾」的串，而合法序列的两端必然都是括号（不可能是 `*`），所以最终答案就是 $dp[1][n][3]$，对应代码中的 `h[1][n]`。

## 逐行代码解析

### 全局定义与六状态数组

```cpp
#include<bits/stdc++.h>
#define endl '\n'
#define fi first
#define se second
#define lowbit(x) (x&(-x))
#define int long long
using namespace std;
typedef pair<int,int> PII;
typedef long long ll;
const int N=510,mod=1e9+7;
int cnt=0,n,k;
string s;
int sr[N][N],b[N][N],f[N][N],h[N][N],c[N][N],tr[N][N];
```

- `#define int long long`：把全程序 `int` 提升为 64 位，避免两个模数级别的数相乘时溢出。
- 六个二维数组 `sr / b / f / h / c / tr` 依次对应状态 0~5，`N=510` 保证 $n \le 500$ 时不越界。
- `cnt`、`PII`、`fi/se/lowbit` 等是模板残留，本题未使用，不影响正确性。

### 括号配对判断 cmk

```cpp
bool cmk(int l,int r){
    if((s[l]=='('||s[l]=='?')&&(s[r]==')'||s[r]=='?')) return true;
    else return false;
}
```

- `cmk(l,r)` 判断位置 $l$、$r$ 能否配成一对括号：左端是 `(` 或 `?`，右端是 `)` 或 `?`。
- 只有 `cmk(l,r)` 成立时才计算状态 1（`b[l][r]`），否则该区间无法被整体包裹。

### 主函数：读入与空区间预处理

```cpp
signed main(){
//    freopen(".in","r",stdin);
//    freopen(".out","w",stdout);
    ios::sync_with_stdio(false);
    cin.tie(nullptr);cout.tie(nullptr);
    cin>>n>>k;
    cin>>s;s=' '+s;
    for(int i=1;i<=n;i++){
        //cout<<s[i];
        sr[i][i-1]=1;
    }
```

- `cin>>n>>k; cin>>s; s=' '+s;`：读入后串首补一个空格，使有效字符下标从 1 开始，与 DP 区间 $[1,n]$ 对齐。
- `sr[i][i-1]=1` 是空区间递归边界，保证 `()`（内部为空）也能被正确计数。
- `freopen` 与 `//cout<<s[i];` 是调试残留，已注释，不影响提交。

### 区间 DP 主循环与状态转移

```cpp
    for(int len=1;len<=n;len++){
        for(int l=1;l<=n-len+1;l++){
            int r=l+len-1;
            //if(len<=k&&sr[l+1][r]==1&&(s[l]=='*'||s[l]=='?')) sr[l][r]=1;
            if(len<=k&&sr[l][r-1]==1&&(s[r]=='*'||s[r]=='?')) sr[l][r]=1;
            if(len>=2){
                bool u=cmk(l,r);
                //cout<<u<<" "<<l<<" "<<r<<"\n";
                if(u) b[l][r]=(sr[l+1][r-1]%mod+f[l+1][r-1]%mod+h[l+1][r-1]%mod+c[l+1][r-1]%mod)%mod;
                for(int i=l;i<r;i++){
                    f[l][r]=(f[l][r]%mod+h[l][i]*sr[i+1][r]%mod)%mod;
                    h[l][r]=(h[l][r]%mod+(f[l][i]+h[l][i])*b[i+1][r]%mod)%mod;
                    c[l][r]=(c[l][r]%mod+(c[l][i]+tr[l][i])*b[i+1][r]%mod)%mod;
                    tr[l][r]=(tr[l][r]%mod+c[l][i]*sr[i+1][r]%mod)%mod;
                }
            }
            h[l][r]=(h[l][r]%mod+b[l][r]%mod)%mod;
            tr[l][r]=(tr[l][r]%mod+sr[l][r]%mod)%mod;
        }
    }
```

- 外层按区间长度递增、内层枚举左端点，保证转移所需的更短区间都已算好。
- `sr[l][r]` 的递推只在 `len<=k` 时进行，落实「`*` 段长度不超过 $k$」的限制。
- `b[l][r]` 对应状态 1（被括号包裹）；`f/h/c/tr` 各自按转移方程累加，循环结束后把状态 1 并入状态 3、状态 0 并入状态 5。
- 所有累加都即时对 `mod` 取模，保持中间量在模意义下。

### 输出答案

```cpp
    cout<<h[1][n];
    // for(int len=1;len<=n;len++){
    //        for(int l=1;l+len-1<=n;l++){
    //            int r=len+l-1;
    //            cout<<l<<" "<<r<<" "<<sr[l][r]<<" "<<b[l][r]<<" "<<f[l][r]<<" "<<h[l][r]<<" "<<c[l][r]<<" "<<tr[l][r]<<"\n";
    //        }
    //    }
    return 0;
}
```

- 答案为 `h[1][n]`，即整串处于状态 3（以括号序列开头、以括号序列结尾）。
- 尾部注释掉的 `for` 块是调试输出整个 DP 表的代码，提交时保持注释即可。

## 复杂度分析

### 时间复杂度

- 状态规模：$n^2$ 个区间，每个区间维护 6 个形态。
- 每个区间在转移时要枚举分割点 $i$，代价 $O(n)$。
- 总复杂度 $O(n^3)$；$n \le 500$ 时约 $1.25 \times 10^8$ 量级，配合较小的常数可以接受。

### 空间复杂度

- 六个 `N×N` 的数组（`sr/b/f/h/c/tr`），规模 $O(6n^2) = O(n^2)$。

## 常见陷阱与注意事项

1. **重复计数的根源**
   - 若不区分形态，`(())` 会同时被「括号包裹」和「拼接」两条路径计数。
   - 状态 1 与 3、状态 0 与 5 必须分开存，转移时各司其职，最后再并入。

2. **状态并入的时机**
   - 代码在每轮区间枚举结束后才执行 `h[l][r] += b[l][r]` 与 `tr[l][r] += sr[l][r]`。
   - 若在转移循环中途就并入，会污染同一轮的后续转移，造成重复。

3. **空区间的 `*` 边界**
   - `sr[i][i-1]=1` 处理了 `()` 这种内部为空串的情况（此时区间 $[l+1, r-1]$ 为空）。

4. **`#define int long long` 的必要性**
   - 转移中出现 `(f[l][i]+h[l][i]) * b[i+1][r]`，两个小于模数的数相乘可达约 $10^{18}$，普通 `int` 会溢出。
   - `signed main()` 是 `long long main` 的等价写法。

5. **下标从 1 开始**
   - 用 `s=' '+s` 在串首补一个空格字符，使下标与 DP 区间 $[1,n]$ 对齐，避免边界特判。

6. **答案取状态 3 的原因**
   - 合法序列首尾必须是括号，因此必然是「以括号序列开头、以括号序列结尾」的状态 3，即 `h[1][n]`。

## 对比与扩展

| 做法 | 时间 | 空间 | 说明 |
|---|---|---|---|
| 六状态区间 DP（本题） | $O(n^3)$ | $O(n^2)$ | 用形态标签去重，$n \le 500$ 可过 |
| 朴素两维区间 DP | $O(n^3)$ | $O(n^2)$ | 未区分形态，合并时重复计数，结果偏大 |
| 记忆化搜索 | $O(n^3)$ | $O(n^2)$ | 思路相近，去重仍需同样的状态拆分 |

### 扩展

- 本题「按首尾形态拆分状态」是区间 DP 计数去重的通用套路，可迁移到「括号着色计数」「表达式拆分计数」等区间计数问题。
- 若去掉 $k$ 限制（`*` 段长度任意），状态 0 与状态 5 会退化为更简单的全 `*` 前缀判断，整体框架不变。
- 与「括号树」「合法括号序列」等经典题一样，都依赖「括号序列可由嵌套与拼接唯一分解」这一核心性质。$AKB482$, '动态规划', array['区间DP', '计数', '括号序列', '状态拆分'], null, '提高+/省选−', 'problem'),
('world-needs-sunday', 'col-prob-p5664-emiya', 'P5664 Emiya 家今天的饭 — 容斥 + 差值DP（CSP-S 2019）', $AKB483$## P5664 Emiya 家今天的饭

## 一、题目描述

Emiya 共掌握 $n$ 种**烹饪方法**，会使用 $m$ 种**主要食材**做菜。每道菜使用恰好一种烹饪方法与恰好一种主要食材。

$a_{i,j}$ 表示使用烹饪方法 $i$ 和主要食材 $j$ 能做出的**不同菜的道数**。

从所有菜中选出一个**非空子集**构成一桌饭，要求：

1. **至少做一道菜**（$k \ge 1$，$k$ 为选出的菜数）
2. **每道菜的烹饪方法互不相同**（每种烹饪方法至多用一次）
3. **每种主要食材至多在一半的菜中被使用**，即对每种食材 $j$：$c_j \le \lfloor \frac{k}{2} \rfloor$，其中 $c_j$ 为使用食材 $j$ 的菜数

求满足所有要求的搭配方案数，对质数 $998244353$ 取模。

### 输入格式

第一行两个整数 $n, m$。

接下来 $n$ 行，每行 $m$ 个整数，第 $i+1$ 行的 $m$ 个数依次为 $a_{i,1}, a_{i,2}, \cdots, a_{i,m}$。

### 输出格式

一行一个整数，表示所求方案数对 $998244353$ 取模的结果。

### 数据范围

- $1 \le n \le 100$
- $1 \le m \le 2000$
- $0 \le a_{i,j} < 998244353$

---

## 二、样例

### 样例 1

**输入：**
```
2 3
1 0 1
0 1 1
```

**输出：**
```
3
```

**解释：** 所有只有 1 道菜的方案都不合法（因为唯一食材占比 $1 > \lfloor 1/2 \rfloor = 0$）。合法的 3 种方案都是 2 道菜且食材不同：(1,1)+(2,2)、(1,1)+(2,3)、(1,3)+(2,2)。

### 样例 2

**输入：**
```
3 3
1 2 3
4 5 0
6 0 0
```

**输出：**
```
190
```

**解释：** 做 2 道菜有 100 种方案，做 3 道菜有 90 种方案，合计 190。

---

## 三、解题思路

### 核心洞察一：先去掉 Yazid 条件——乘法原理

暂时忽略"每种食材至多占一半"的约束，只考虑：

- 每种烹饪方法至多用一次
- 可以不选

对第 $i$ 种烹饪方法，局部选择有：

- **完全不用**：$1$ 种
- **选一道菜**：选一个食材 $j$，有 $a_{i,j}$ 种具体菜，共 $\sum_{j=1}^{m} a_{i,j} = s_i$ 种

因此第 $i$ 行共有 $s_i + 1$ 种选择。各行独立，由乘法原理：

$$
\text{总方案（含空集）} = \prod_{i=1}^{n} (s_i + 1)
$$

> ⚠️ 注意：是 $s_i + 1$ 不是 $s_i$，"不用"也算一种选择。也不是 $2^{s_i} - 1$，因为"烹饪方法互不相同"限定每行最多选一道菜。

---

### 核心洞察二：超标食材至多只有一个

这是整道题最关键的观察。

**反证**：假设存在两种食材 $j_1$ 和 $j_2$ 都超标，即 $c_{j_1} > \lfloor k/2 \rfloor$ 且 $c_{j_2} > \lfloor k/2 \rfloor$，则：

- 若 $k$ 为偶数：$c_{j_1} + c_{j_2} \ge 2 \cdot (k/2 + 1) = k + 2 > k$
- 若 $k$ 为奇数：$c_{j_1} + c_{j_2} \ge 2 \cdot ((k-1)/2 + 1) = k + 1 > k$

但每道菜只含一种主要食材，所以 $c_{j_1} + c_{j_2} \le k$，矛盾。

**结论：一个方案中，最多只有一种食材超标。**

这条定理的价值在于：**不合法方案可以按"哪种食材超标"分成互不相交的 $m$ 类**，因此可以直接相加，不需要复杂的容斥系数。

设 $S_j$ 为"食材 $j$ 超标"的方案数，则：

$$
\text{合法方案} = \text{总方案} - 1 - \sum_{j=1}^{m} S_j \pmod{q}
$$

其中 $-1$ 是去掉空集。

---

### 核心洞察三：超标 = 差值大于 0

对固定的食材 $j$，定义差值：

$$
d = c_j - (k - c_j) = 2c_j - k
$$

- $c_j$：含食材 $j$ 的菜数
- $k - c_j$：不含食材 $j$ 的菜数

**结论：$c_j > \lfloor k/2 \rfloor \iff d > 0$**

证明（奇偶分情况）：

- $k$ 偶：$\lfloor k/2 \rfloor = k/2$，$c_j > k/2 \iff 2c_j > k \iff d > 0$
- $k$ 奇：$\lfloor k/2 \rfloor = (k-1)/2$，$c_j > (k-1)/2 \iff 2c_j > k-1 \iff 2c_j \ge k+1 \iff d > 0$

**为什么这一步是决定性的？** 原本判断超标需要同时知道 $k$ 和 $c_j$ 两个量（二维状态），现在只需一个差值 $d$（一维状态）。DP 的状态维度直接塌缩了一半。

---

### 核心洞察四：差值 DP 的设计

固定食材 $j$ 后，对第 $i$ 种烹饪方法，有三种选择：

| 选择 | 对差值 $d$ 的影响 | 权重（方案数） |
|------|-------------------|---------------|
| 完全不用第 $i$ 种烹饪方法 | $0$ | $1$ |
| 用它做一道**含 $j$** 的菜 | $+1$ | $a_{i,j}$ |
| 用它做一道**不含 $j$** 的菜 | $-1$ | $s_i - a_{i,j}$ |

差值 $d$ 的范围是 $[-n, n]$（因为烹饪方法互不相同，总菜数 $k \le n$，故 $|d| \le k \le n$）。

整体偏移 $n$，用下标 $k' = d + n \in [0, 2n]$ 存储（避免负下标）。

**状态定义：**

$$
dp[i][k'] = \text{处理完前 } i \text{ 种烹饪方法，偏移后差值下标为 } k' \text{ 的方案数}
$$

**初始状态：**

$$
dp[0][n] = 1 \quad \text{（什么都没选，} d=0\text{，一种方案）}
$$

**转移方程：**

$$
\begin{aligned}
dp[i][k'] &+= dp[i-1][k'] \quad &\text{（不用第 } i \text{ 种）} \\
dp[i][k'] &+= dp[i-1][k'-1] \times a_{i,j} \quad &\text{（用且含 } j\text{，} d+1\text{）} \\
dp[i][k'] &+= dp[i-1][k'+1] \times (s_i - a_{i,j}) \quad &\text{（用且不含 } j\text{，} d-1\text{）}
\end{aligned}
$$

**食材 $j$ 超标的方案数：**

$$
S_j = \sum_{k'=n+1}^{2n} dp[n][k']
$$

即 $d > 0$ 的所有方案数之和。

---

### 最终答案

$$
\text{答案} = \left( \prod_{i=1}^{n} (s_i + 1) - 1 - \sum_{j=1}^{m} S_j \right) \bmod 998244353
$$

注意负数处理：$((ans \bmod q) + q) \bmod q$。

---

## 四、逐行代码解析

### 全局变量

```cpp
#include<bits/stdc++.h>
using namespace std;
const long long q = 998244353;
long long ans = 1;
vector<vector<long long>> A, dp;
vector<long long> sum_n;
```

- `q`：模数 $998244353$。
- `A[i][j]`：烹饪方法 $i$ + 食材 $j$ 的菜的道数；`sum_n[i]`：第 $i$ 行总和 $s_i$。
- `dp[i][k']`：前 $i$ 种烹饪方法、偏移后差值下标 $k'$ 的方案数。

### init：初始化

```cpp
void init(int n,int m)
{
    ans = 1;
    A.assign(n + 1, vector<long long>(m + 1, 0));
    sum_n.assign(n + 1, 0);
    dp.assign(n + 1, vector<long long>(2 * n + 2, 0));
}
```

- `dp` 第一维 $n+1$（烹饪方法数），第二维 $2n+2$（偏移后差值范围 $[0,2n]$）。

### 读入矩阵并求行和

```cpp
    for (int i = 1; i <= n; i++)
    {
        for (int j = 1; j <= m; j++)
        {
            cin >> A[i][j];
            A[i][j] %= q;
            sum_n[i] = (A[i][j] + sum_n[i]) % q;
        }
    }
```

- 边读边取模；`sum_n[i]` 同时累加每行和。

### 含空集的总方案数

```cpp
    for (int i = 1; i <= n; i++) ans = (ans * (sum_n[i] + 1)) % q;
```

- $\prod (s_i + 1)$：每个方法「不用」也算一种，所以是 $s_i+1$。

### DP 初值

```cpp
    dp[0][n] = 1;
```

- 什么都没选时差值 $d=0$（偏移后下标 $n$），方案数 $1$。

### DP 主循环（对每种食材跑一遍）

```cpp
    for (int j = 1; j <= m; j++)
    {
        for (int i = 1; i <= n; i++)
        {
            for (int k = 0; k <= 2 * n; k++)
            {
                dp[i][k] = dp[i - 1][k];
                if (k != 0) dp[i][k] = (dp[i][k] + (dp[i - 1][k - 1] * A[i][j]) % q) % q;
                if (k != 2 * n) dp[i][k] = (dp[i][k] + (dp[i - 1][k + 1] * ((sum_n[i] - A[i][j] + q) % q)) % q) % q;
            }
        }

        for (int i = n + 1; i <= 2 * n; i++) ans -= dp[n][i];
    }
```

- ① 不用第 $i$ 种方法：`dp[i][k] = dp[i-1][k]`。
- ② 用且含食材 $j$：差值 $+1$，从 $k-1$ 转移，权重 $A[i][j]$。
- ③ 用且不含食材 $j$：差值 $-1$，从 $k+1$ 转移，权重 $s_i - a_{i,j}$。
- `(sum_n[i] - A[i][j] + q) % q`：减法后加 $q$ 再取模，避免负数。
- 跑完 $n$ 行，把 $d>0$（下标 $n+1\sim 2n$）的方案数从答案里减去。

### 输出去空集

```cpp
    ans -= 1;
    while (ans < 0) ans += q;
    cout << ans;
```

- 最后 $-1$ 去掉空集，处理负数后输出。

> 💡 `dp` 没有在每个 $j$ 之间清零，但依然正确：第 0 行始终 `dp[0][n] = 1`，第 $1..n$ 行每轮都被完整重算（赋值而非累加）。这是结构上的巧合，更稳妥的写法是每轮重置或使用滚动数组。
## 五、复杂度分析

### 时间复杂度：$O(n^2 m)$

- 外层枚举食材：$O(m)$
- 中层枚举烹饪方法：$O(n)$
- 内层枚举差值状态：$O(n)$
- 总运算量：$m \times n \times 2n = O(n^2 m)$

代入最大数据：$2000 \times 100 \times 200 \approx 4 \times 10^7$ 次简单运算，1 秒内轻松通过。

### 空间复杂度：$O(n^2)$

- `dp` 数组：$(n+1) \times (2n+2)$ 个 `long long`，约 $100 \times 200 \times 8 \text{B} \approx 160 \text{KB}$

**可优化：** 由于 `dp[i]` 只依赖 `dp[i-1]`，可以用滚动数组把空间降到 $O(n)$。

---

## 六、常见陷阱与注意事项

1. **总方案漏了"不用"**  
   第 $i$ 种烹饪方法的局部选择是 $s_i + 1$，不是 $s_i$。"完全不用"也算一种选择。

2. **DP 初值写成 0**  
   `dp[0][n] = 1` 而不是 0。"一道菜都不选"本身是一种方案，初值是计数不是布尔。

3. **dp 第一维写错**  
   DP 是沿烹饪方法（$n$）推进，第一维必须是 $n+1$，不是 $m+1$。$m$ 是外层循环次数，不是 DP 阶段数。

4. **权重写错**  
   "含 $j$"的权重是 $a_{i,j}$，"不含 $j$"的权重是 $s_i - a_{i,j}$。不要写成 $s_i \times (m-1)$ 之类毫无依据的式子。权重必须能在题面里逐字对应。

5. **累加区间反了**  
   超标对应 $d > 0$，即**下标大于 $n$**（$n+1$ 到 $2n$），不是下标 $1$ 到 $n$。加了偏移之后，"下标"和"差值"是两个概念，不要混淆。

6. **$s_i - a_{i,j}$ 可能为负**  
   模意义下的减法要加 $q$ 再取模：`(sum_n[i] - A[i][j] + q) % q`。

7. **最终答案可能为负**  
   多次做减法后 `ans` 可能变成负数，最后要用 `(ans % q + q) % q` 修正。

8. **空集只减一次**  
   空集的 $d=0$（下标 $n$），不会被任何 $S_j$ 包含，所以最后的 $-1$ 只需要减一次。

9. **$k=1$ 时必然不合法**  
   只有 1 道菜时，唯一的食材占比 $1 > \lfloor 1/2 \rfloor = 0$，必然超标。这是样例 1 中单菜方案全不合法的原因。

10. **超标食材至多一个**  
    这是容斥的前提，也是这道题最核心的观察。没有这个结论，就无法把不合法方案简单相加。

---

## 七、一句话总结

> **"每种食材至多占一半"通过"超标者至多一个"变成了可加的容斥项；再通过"含 $j$ 菜数 $-$ 不含 $j$ 菜数 $> 0$"把二维条件塌缩成一维差值 DP。前者给了容斥的合法性，后者给了 DP 的可行性——两个观察缺一不可。**$AKB483$, '动态规划', array['动态规划', '计数DP', '容斥原理', '差值DP', 'CSP-S'], null, '提高+/省选−', 'problem'),
('world-needs-sunday', 'col-prob-two-digit-string', '两位数字符串（前缀和取模 + LCS）', $AKB484$## 题目描述

给定两个仅由数字组成的字符串 $a$ 和 $b$。一次操作中，你可以在任意一个字符串里选择两个相邻字符，把它们替换为两者的和模 10。例如：

```
57246 → 2246  (5+7=12 → 2)
57246 → 5946  (7+2=9)
57246 → 5766  (2+4=6)
57246 → 5720  (4+6=10 → 0)
```

每次操作后字符串长度恰好减 1。你可以执行任意多次操作（包括零次），必须使两个字符串相等（$|a| = |b|$ 且对应每个位置的字符都相同）。求最终得到的相同字符串的**最大可能长度**；若无法使它们相等，输出 $-1$。

### 输入格式

- 第一行：$t$（$1 \le t \le 2 \times 10^3$）
- 每组数据两行：字符串 $a$ 和 $b$（$1 \le |a|, |b| \le 5 \times 10^3$，仅含数字）

保证 $\sum (|a| + |b|) \le 10^4$。

### 输出格式

每组数据输出一个整数。

### 数据范围

- $1 \le t \le 2 \times 10^3$
- $1 \le |a|, |b| \le 5 \times 10^3$，字符串仅含数字
- $\sum (|a| + |b|) \le 10^4$

## 样例

> 官方样例共 3 组，其中一组的两个字符串在可访问的题面镜像中未公开。下面两组的数据取自官方题面说明，并已用暴力枚举复核。

### 样例输入

```
2
5147
44441
123450
012345
```

### 样例输出

```
2
5
```

- 第一组：`5147` 与 `44441` 都能归约到 `61`，最长相同串长度为 2。
- 第二组：`123450` 与 `012345` 都能归约到 `12345`，最长相同串长度为 5。

## 解题思路

### 第一步：操作的本质——"切香肠"

把字符串想象成一根香肠，每次操作把相邻两段捏成一段，新段的值 = 两段之和的个位数。捏一通之后，串里的每个字符都对应原串中**连续的一段**，值 = 该段数字之和模 10。

**关键结论**：任意一种"切段方案"都能通过捏合实现，且段与段之间互不打扰（加法可任意结合，每段内部从左往右捏到底即可）。因此问题完全等价于：

> 给 $a$ 选一种切成 $L$ 段的方案，给 $b$ 也选一种切成 $L$ 段的方案，要求两者的"每段之和模 10 的序列"完全相同。$L$ 越大越好。

### 第二步：换记账方式——前缀和模 10 的"读数链"

逐段比较段和太繁琐，换一种记账方式：想象一个里程表从左到右扫过原串，每碰到一个切点就记录"到目前为止扫过的所有数字之和模 10"。

设前缀和模 10 序列为 $p_0 = 0, p_1, p_2, \ldots, p_n$（$p_0 = 0$ 为哨兵，$p_n = \text{sum}(a) \bmod 10$）。则：

- 第 $i$ 段的值 $= (p_i - p_{i-1}) \bmod 10$
- 两条读数链相同 $\iff$ 每个"读数差"相同 $\iff$ 最终串逐字符相同

问题转化为：找一条尽量长的读数链 $w_0 \to w_1 \to \cdots \to w_L$，使得 $a$ 和 $b$ 中都存在一串递增的切点位置，每个切点上的前缀和模 10 恰好是链上对应的值。

### 第三步：链的头尾"焊死"

- **链头**：第一个切点必然是位置 0，读数 $= 0$，没有选择
- **链尾**：最后一个切点必然是串尾，读数 $= \text{sum}(a) \bmod 10 = \text{sum}(b) \bmod 10$（记为 $S$），也没有选择

**$-1$ 的来源**：最终串的和 $\equiv \text{sum}(a) \pmod{10}$，同时 $\equiv \text{sum}(b) \pmod{10}$。若两者个位不同，永远不可能相等，输出 $-1$。

**$-1$ 之外一定有解**：个位相同时，两边全部捏成一团，各自得到 $S$，长度 1 的公共串总可以做得到。

### 第四步：核心——中间部分就是 LCS

链的中间部分 $w_1, \ldots, w_{L-1}$ 需要在 $a$ 的中间读数序列（位置 1 到 $n-1$ 的前缀和模 10）中按顺序出现，也要在 $b$ 的中间读数序列中按顺序出现——这正是**最长公共子序列（LCS）**的定义。

$$\boxed{\text{答案} = \text{LCS}(\text{midA}, \text{midB}) + 1}$$

其中 $\text{midA}$ 是 $a$ 的位置 1 到 $n-1$ 上的前缀和模 10 序列（去掉头 0 和尾 $S$），$\text{midB}$ 同理。

**为什么必须 DP、不能贪心**：例如 $\text{midA} = [1, 2, 3]$，$\text{midB} = [2, 3, 1]$。贪心地一见到 1 就匹配只得 1 个；而正确答案是先放过 1，匹配 2、3，得 2 个。早匹配可能堵死后面的匹配，必须用 DP 全局考虑。

### 完整例子走查

**例 1**：$a = 123$，$b = 321$

- $a$ 前缀和模 10：$[0, 1, 3, 6]$；$b$ 前缀和模 10：$[0, 3, 5, 6]$。尾都是 6 $\checkmark$
- $\text{midA} = [1, 3]$，$\text{midB} = [3, 5]$。LCS $= [3]$，长度 1
- 答案 $= 1 + 1 = 2$。链 $0 \to 3 \to 6$，读数差 $33$

**例 2**：$a = 3111$，$b = 1311$

- $a$ 读数：$[0, 3, 4, 5, 6]$；$b$ 读数：$[0, 1, 4, 5, 6]$。尾都是 6 $\checkmark$
- $\text{midA} = [3, 4, 5]$，$\text{midB} = [1, 4, 5]$。LCS $= [4, 5]$，长度 2
- 答案 $= 3$。链 $0 \to 4 \to 5 \to 6$，读数差 $411$

**例 3**：$a = 55$，$b = 555$。个位 $0 \ne 5$，输出 $-1$。

## 逐行代码解析

### 快速输入

```cpp
inline void read(vector<int>& arr)
{
    arr.clear();
    arr.emplace_back(0);      // 哨兵：位置 0 的前缀和 = 0
    char ch = getchar();
    while (ch < '0' || ch > '9') ch = getchar();  // 跳过非数字字符（换行等）
    while (ch >= '0' && ch <= '9')
    {
        arr.emplace_back(ch - 48);  // 存原始数字值
        ch = getchar();
    }
}
```

- `arr[0] = 0`：哨兵，使前缀和计算统一（$p_0 = 0$）
- 读入后 `arr` 为 $[0, d_1, d_2, \ldots, d_n]$，长度 $n+1$

### 前缀和模 10（原地转换）

```cpp
for (int i = 1; i < A.size(); i++) A[i] = (A[i] + A[i - 1]) % 10;
```

将原始数字序列原地转换为前缀和模 10 序列。此时 `A` 为 $[0, p_1, p_2, \ldots, p_n]$，其中 $p_i = (\sum_{k=1}^{i} d_k) \bmod 10$。

### LCS 动态规划

```cpp
vector<vector<int>> dp(A.size(), vector<int>(B.size(), 0));
for (int i = 1; i < A.size(); i++)
{
    for (int j = 1; j < B.size(); j++)
    {
        if (A[i] == B[j]) dp[i][j] = dp[i - 1][j - 1] + 1;
        else dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
    }
}
```

- **状态定义**：`dp[i][j]` = `A[1..i]` 与 `B[1..j]` 的 LCS 长度
- **转移方程**：
  - `A[i] == B[j]`：当前读数可以配对，`dp[i][j] = dp[i-1][j-1] + 1`
  - 否则：取两边末尾不用的较大值，`dp[i][j] = max(dp[i-1][j], dp[i][j-1])`
- **下标从 1 开始**：`A[0] = B[0] = 0`（哨兵），LCS 从位置 1 开始匹配，等价于"链头 0 已自动匹配"

### 输出

```cpp
if (A.back() == B.back()) write(dp[A.size() - 1][B.size() - 1]);
else write(-1);
```

- `A.back()` 和 `B.back()` 分别是两串的总和模 10（链尾 $S$）
- 若两者不同，输出 $-1$
- 若相同，输出 `dp[n][m]`，即完整前缀和序列的 LCS 长度。由于链头 0 和链尾 $S$ 必然匹配，完整 LCS $=$ 中间 LCS $+ 2$，答案 $=$ 完整 LCS $- 1$。但代码直接用完整序列做 LCS，$\text{dp}[n][m]$ 已经包含链头和链尾的匹配，恰好等于答案

## 复杂度分析

### 时间复杂度

| 操作 | 复杂度 | 说明 |
|---|---|---|
| 前缀和模 10 | $O(n + m)$ | 两个串各一次线性扫描 |
| LCS DP | $O(nm)$ | 二维 DP 表 |
| **总计** | $O(nm)$ | DP 主导 |

单组最坏 $n = m = 5000$，DP 约 $2.5 \times 10^7$ 步，$\sum(|a|+|b|) \le 10^4$ 保证不会多组同时最大。

### 空间复杂度

| 实现 | 空间 | 说明 |
|---|---|---|
| 二维 DP 表 | $O(nm)$ | 本实现，直观 |
| 滚动数组优化 | $O(\min(n,m))$ | 只保留两行，适合内存受限场景 |

## 常见陷阱与注意事项

1. **忘记 $-1$ 判定**
   - 总和模 10 不同时永远不可能相等，必须先检查 `A.back() == B.back()`

2. **端点处理**
   - 代码使用完整前缀和序列（含头 0 和尾 $S$）做 LCS，答案直接是 `dp[n][m]`
   - 若用去掉头尾的中间序列做 LCS，答案 $= \text{LCS}(\text{midA}, \text{midB}) + 1$
   - 两种口径不能混用

3. **LCS 不能用贪心**
   - 贪心匹配会堵死后续匹配，必须用 DP 全局考虑

4. **前缀和必须取模 10**
   - 读数链的值是 $\bmod 10$ 意义下的，直接比前缀和（不取模）会导致错误

5. **$n = 1$ 或 $m = 1$ 的边界**
   - 中间序列为空，在同余前提下答案为 1（两边都是单字符，已相等）

6. **哨兵 `A[0] = 0` 的作用**
   - 使前缀和计算统一，同时使 LCS 的 `dp[0][j] = dp[i][0] = 0` 自动初始化

## 对比与扩展

| 方法 | 时间 | 空间 | 特点 |
|---|---|---|---|
| **前缀和模 10 + LCS DP（本算法）** | $O(nm)$ | $O(nm)$ 或滚动 $O(\min(n,m))$ | 问题转化 + 经典 DP |
| 暴力模拟所有操作 | 指数级 | $O(n+m)$ | 枚举所有捏合方式，不可行 |
| 贪心匹配 | $O(n+m)$ | $O(1)$ | 似是而非，反例已说明 |

### 扩展

- **问题转化思维**：将"捏合操作"转化为"切段方案"，再转化为"前缀和读数链"，最终归约为 LCS——这是一条经典的"操作 $\to$ 切分 $\to$ 前缀和 $\to$ 子序列"转化链
- **模意义下的前缀和**：前缀和取模后值域缩小到 $0 \sim 9$，但 LCS 不能利用这一点加速（仍需 DP 保证全局最优）
- **滚动数组优化**：LCS 只依赖上一行，可用两行滚动数组将空间降至 $O(\min(n,m))$$AKB484$, '动态规划', array['字符串', '前缀和', '取模', 'LCS', '动态规划', '贪心转DP', '构造'], null, '暂未评定', 'problem'),
